          requireLength("ADOSC", "inHigh", inHigh, guardInLen);
          requireLength("ADOSC", "inLow", inLow, guardInLen);
          requireLength("ADOSC", "inClose", inClose, guardInLen);
          requireLength("ADOSC", "inVolume", inVolume, guardInLen);
