          double lag1_inOpen;
          double lag2_inOpen;
          double lag3_inOpen;
          double lag1_inHigh;
          double lag2_inHigh;
          double lag3_inHigh;
          double lag1_inLow;
          double lag2_inLow;
          double lag3_inLow;
          double lag1_inClose;
          double lag2_inClose;
          double lag3_inClose;
          int ringPos_NearTrailingIdx;
          int ringCap_NearTrailingIdx;
          int ringLag_NearTrailingIdx;
