          requireLength("CDL3STARSINSOUTH", "inHigh", inHigh, guardInLen);
          requireLength("CDL3STARSINSOUTH", "inLow", inLow, guardInLen);
          requireLength("CDL3STARSINSOUTH", "inClose", inClose, guardInLen);
