          requireLength("CDLCOUNTERATTACK", "inLow", inLow, guardInLen);
          requireLength("CDLCOUNTERATTACK", "inClose", inClose, guardInLen);
          requireLength("CDLCOUNTERATTACK", "outInteger", outInteger, guardOutLen);
