       /* cdldojistarOpenAndFill anchored at startIdx — the composed-open fusion seam. */
       CdldojistarStream cdldojistarOpenAndFillInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx, MInteger outBegIdx, MInteger outNBElement, int outInteger[] )
       {
          CdldojistarStream sp = new CdldojistarStream(this);
          RetCode retCode = cdldojistarOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("CDLDOJISTAR openAndFill: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("CDLDOJISTAR openAndFill: internal error", retCode);
          }
          throw new TaLibArgumentException("CDLDOJISTAR openAndFill: " + retCode, retCode);
       }
       /* Internal startIdx-anchored open behind cdldojistarOpen (composition seam). */
       CdldojistarStream cdldojistarOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
       {
          CdldojistarStream sp = new CdldojistarStream(this);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          int[] sink_outInteger = new int[1];
          RetCode retCode = cdldojistarOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, sink_outInteger, 0);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("CDLDOJISTAR open: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("CDLDOJISTAR open: internal error", retCode);
          }
          throw new TaLibArgumentException("CDLDOJISTAR open: " + retCode, retCode);
       }
       /**
        * Open a live CDLDOJISTAR stream over the warm-up history; the handle's
        * {@code value()} starts at the last history bar's value — bit-identical
        * to {@link Core#CDLDOJISTAR} at that bar.
        * <p>The history must hold at least {@code CDLDOJISTAR_Lookback(...) + 1} bars
        * (unstable-period aware), or {@link InsufficientHistoryException} is
        * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
        * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
        * default, as in the batch API). An EMPTY history throws
        * {@link IndexOutOfBoundsException} — its implied {@code startIdx} of 0
        * names no bar — and a null argument {@link IllegalArgumentException},
        * both ahead of everything above.
        */
       public CdldojistarStream cdldojistarOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
       {
          requireArgument("CDLDOJISTAR open", "inOpen", inOpen);
          requireHistory("CDLDOJISTAR open", inOpen.length);
          requireArgument("CDLDOJISTAR open", "inHigh", inHigh);
          requireArgument("CDLDOJISTAR open", "inLow", inLow);
          requireArgument("CDLDOJISTAR open", "inClose", inClose);
          requireHistoryLength("CDLDOJISTAR open", "inHigh", inHigh.length, inOpen.length);
          requireHistoryLength("CDLDOJISTAR open", "inLow", inLow.length, inOpen.length);
          requireHistoryLength("CDLDOJISTAR open", "inClose", inClose.length, inOpen.length);
          return cdldojistarOpenInternal(inOpen, inHigh, inLow, inClose, 0);
       }
       /**
        * {@link Core#cdldojistarOpen} that also fills the output array(s) bit-identically
        * to {@link Core#CDLDOJISTAR} over the whole history in the same single pass
        * (no separate batch call needed for the warm-up plot). Output arrays must
        * not alias the inputs or each other, and must hold
        * {@code historyLen - lookback} values — both checked before anything is
        * written, so an undersized array is an {@link IllegalArgumentException}
        * naming it rather than a fault from inside the fill.
        * <p>The range written is on the returned handle:
        * {@link CdldojistarStream#outRange()}.
        */
       public CdldojistarStream cdldojistarOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], int outInteger[] )
       {
          requireArgument("CDLDOJISTAR openAndFill", "inOpen", inOpen);
          requireHistory("CDLDOJISTAR openAndFill", inOpen.length);
          requireArgument("CDLDOJISTAR openAndFill", "inHigh", inHigh);
          requireArgument("CDLDOJISTAR openAndFill", "inLow", inLow);
          requireArgument("CDLDOJISTAR openAndFill", "inClose", inClose);
          int guardOutLen = openFillCount("CDLDOJISTAR openAndFill", inOpen.length, CDLDOJISTAR_Lookback());
          requireHistoryLength("CDLDOJISTAR openAndFill", "inHigh", inHigh.length, inOpen.length);
          requireHistoryLength("CDLDOJISTAR openAndFill", "inLow", inLow.length, inOpen.length);
          requireHistoryLength("CDLDOJISTAR openAndFill", "inClose", inClose.length, inOpen.length);
          requireLength("CDLDOJISTAR openAndFill", "outInteger", outInteger, guardOutLen);
          if( (Object)outInteger == (Object)inOpen || (Object)outInteger == (Object)inHigh || (Object)outInteger == (Object)inLow || (Object)outInteger == (Object)inClose ) {
             throw new TaLibArgumentException("CDLDOJISTAR openAndFill: " + RetCode.BadParam, RetCode.BadParam);
          }
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          return cdldojistarOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, outBegIdx, outNBElement, outInteger);
       }
