          RetCode retCode = cdlhammerOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, sink_outInteger, 0);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
