          requireLength("CDLINVERTEDHAMMER", "inLow", inLow, guardInLen);
          requireLength("CDLINVERTEDHAMMER", "inClose", inClose, guardInLen);
          requireLength("CDLINVERTEDHAMMER", "outInteger", outInteger, guardOutLen);
