          requireArgument("CDLSEPARATINGLINES open", "inLow", inLow);
          requireArgument("CDLSEPARATINGLINES open", "inClose", inClose);
          requireHistoryLength("CDLSEPARATINGLINES open", "inHigh", inHigh.length, inOpen.length);
