          requireLength("CDLSTALLEDPATTERN", "inClose", inClose, guardInLen);
          requireLength("CDLSTALLEDPATTERN", "outInteger", outInteger, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
