          int ringPos_BodyShortTrailingIdx;
          int ringCap_BodyShortTrailingIdx;
          double[] ring_BodyShortTrailingIdx_derived;
          int cs_BodyLong_rangeType;
          int cs_BodyLong_avgPeriod;
          double cs_BodyLong_factor;
