          RetCode retCode = cdlxsidegap3methodsOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
