             Re = Math.fma(0.8, Re, 0.2 * (Math.fma(I2, prevI2, Q2 * prevQ2)));
             Im = Math.fma(0.8, Im, 0.2 * (I2 * prevQ2 - Q2 * prevI2));
             prevQ2 = Q2;
             prevI2 = I2;
             tempReal = period;
             if( Im != 0.0 && Re != 0.0 ) {
                period = 360.0 / (Math.atan(Im / Re) * rad2Deg);
             }
             tempReal2 = 1.5 * tempReal;
             if( period > tempReal2 ) {
                period = tempReal2;
             }
             tempReal2 = 0.67 * tempReal;
             if( period < tempReal2 ) {
                period = tempReal2;
             }
             if( period < 6 ) {
                period = 6;
             } else if( period > 50 ) {
                period = 50;
             }
             period = Math.fma(0.2, period, 0.8 * tempReal);
             smoothPeriod = Math.fma(0.67, smoothPeriod, 0.33 * period);
             DCPeriod = smoothPeriod + 0.5;
             DCPeriodInt = (int)DCPeriod;
             tempReal = 0.0;
             for( i = 0; i < 50; i += 1 ) {
                if( i < DCPeriodInt ) {
                   tempReal += (double)inReal[today - i];
                }
             }
             if( DCPeriodInt > 0 ) {
                tempReal = tempReal / (double)DCPeriodInt;
             }
             tempReal2 = (Math.fma(2.0, iTrend2, Math.fma(4.0, tempReal, 3.0 * iTrend1)) + iTrend3) / 10.0;
             iTrend3 = iTrend2;
             iTrend2 = iTrend1;
             iTrend1 = tempReal;
             if( today >= startIdx ) {
                outReal[outIdx++] = tempReal2;
             }
             today += 1;
