          double I1ForOddPrev3 = 0;
          double I1ForEvenPrev2 = 0;
          double I1ForEvenPrev3 = 0;
          double rad2Deg = 0;
          double deg2Rad = 0;
          double constDeg2RadBy360 = 0;
          double todayValue = 0;
          double smoothPeriod = 0;
          double[] smoothPrice;
          int smoothPrice_Idx = 0;
          int maxIdx_smoothPrice = (50)-1;
          int idx = 0;
          int DCPeriodInt = 0;
          double DCPhase = 0;
          double DCPeriod = 0;
          double imagPart = 0;
          double realPart = 0;
          int daysInTrend = 0;
          int trend = 0;
          double prevDCPhase = 0;
          double trendline = 0;
          double prevSine = 0;
          double prevLeadSine = 0;
          double sine = 0;
          double leadSine = 0;
