          b = 0.5769;
          smoothPrice = new double[maxIdx_smoothPrice+1];
          iTrend3 = 0.0;
          iTrend2 = iTrend3;
          iTrend1 = iTrend2;
          daysInTrend = 0;
          DCPhase = 0.0;
          prevDCPhase = DCPhase;
          sine = 0.0;
          prevSine = sine;
          leadSine = 0.0;
          prevLeadSine = leadSine;
          tempReal = Math.atan(1);
          rad2Deg = 45.0 / tempReal;
          deg2Rad = 1.0 / rad2Deg;
          constDeg2RadBy360 = tempReal * 8.0;
