          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("LINEARREG_SLOPE", "inReal", inReal, guardInLen);
          requireLength("LINEARREG_SLOPE", "outReal", outReal, guardOutLen);
