       /**
        * Number of leading input bars {@link Core#SUM} consumes before it can
        * produce its first value.
        * <p>Equivalently, the index of the first bar with a value when the whole
        * series is requested. Feed at least {@code lookback + 1} bars to get any
        * output.
        *
        * @param optInTimePeriod Window length summed (default 30; range 2..100000;
        *        {@code Integer.MIN_VALUE} selects the default).
        * @return The lookback, or {@code -1} if a parameter is out of range.
        */
       public int SUM_Lookback( int optInTimePeriod )
       {
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 30;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return -1;
          }
          return optInTimePeriod - 1 ;

       }
       RetCode SUM_Impl( int startIdx,
                         int endIdx,
                         double inReal[],
                         int optInTimePeriod,
                         MInteger outBegIdx,
                         MInteger outNBElement,
                         double outReal[] )
       {
          double periodTotal = 0;
          double tempReal = 0;
          int i = 0;
          int outIdx = 0;
          int trailingIdx = 0;
          int lookbackTotal = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 30;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          /* Identify the minimum number of price bar needed
           * to calculate at least one output.
           */
          lookbackTotal = optInTimePeriod - 1;
          /* Move up the start index if there is not
           * enough initial data.
           */
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.Success ;
          }
          /* Do the MA calculation using tight loops. */
          /* Add-up the initial period, except for the last value. */
          periodTotal = 0;
          trailingIdx = startIdx - lookbackTotal;
          i = trailingIdx;
          if( optInTimePeriod > 1 ) {
             while( i < startIdx ) {
                periodTotal += inReal[i++];
             }
          }
          /* Proceed with the calculation for the requested range.
           * Note that this algorithm allows the inReal and
           * outReal to be the same buffer.
           */
          outIdx = 0;
          do {
             periodTotal += inReal[i++];
             tempReal = periodTotal;
             periodTotal -= inReal[trailingIdx++];
             outReal[outIdx++] = tempReal;
          } while( i <= endIdx );
          /* All done. Indicate the output limits and return. */
          outNBElement.value = outIdx;
          outBegIdx.value = startIdx;
          return RetCode.Success ;
       }
       RetCode SUM_Impl( int startIdx,
                         int endIdx,
                         float inReal[],
                         int optInTimePeriod,
                         MInteger outBegIdx,
                         MInteger outNBElement,
                         double outReal[] )
       {
          double periodTotal = 0;
          double tempReal = 0;
          int i = 0;
          int outIdx = 0;
          int trailingIdx = 0;
          int lookbackTotal = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 30;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          lookbackTotal = optInTimePeriod - 1;
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.Success ;
          }
          periodTotal = 0;
          trailingIdx = startIdx - lookbackTotal;
          i = trailingIdx;
          if( optInTimePeriod > 1 ) {
             while( i < startIdx ) {
                periodTotal += (double)inReal[i++];
             }
          }
          outIdx = 0;
          do {
             periodTotal += (double)inReal[i++];
             tempReal = periodTotal;
             periodTotal -= (double)inReal[trailingIdx++];
             outReal[outIdx++] = tempReal;
          } while( i <= endIdx );
          outNBElement.value = outIdx;
          outBegIdx.value = startIdx;
          return RetCode.Success ;
       }
       /**
        * Rolling sum of the input over a fixed period. Each output is the sum of
        * the most recent optInTimePeriod input values.
        * <p><b>Formula</b>
        * <pre>{@code
        * $out_i = \sum_{j=i-(N-1)}^{i} inReal_j$, N = optInTimePeriod
        * }</pre>
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#SUM_Lookback} is a <b>success with no
        * values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inReal Values to sum.
        * @param optInTimePeriod Window length summed (default 30; range 2..100000;
        *        {@code Integer.MIN_VALUE} selects the default).
        * @param outReal Windowed sum over the period. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#SMA
        */
       public OutRange SUM( int startIdx,
                            int endIdx,
                            double inReal[],
                            int optInTimePeriod,
                            double outReal[] )
       {
          requireIndexRange("SUM", startIdx, endIdx);
          int guardStart = clampedStart("SUM", startIdx, SUM_Lookback(optInTimePeriod));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("SUM", "inReal", inReal, guardInLen);
          requireLength("SUM", "outReal", outReal, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = SUM_Impl(startIdx, endIdx, inReal, optInTimePeriod, outBegIdx, outNBElement, outReal);
          if( retCode != RetCode.Success ) {
             throw failure("SUM", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
       /**
        * Rolling sum of the input over a fixed period. Each output is the sum of
        * the most recent optInTimePeriod input values.
        * <p><b>Formula</b>
        * <pre>{@code
        * $out_i = \sum_{j=i-(N-1)}^{i} inReal_j$, N = optInTimePeriod
        * }</pre>
        * <p>This is the {@code float[]} overload. The arithmetic is performed in
        * {@code double} before being written to the {@code double[]} output, so a
        * result beyond {@code float} range is still representable.
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#SUM_Lookback} is a <b>success with no
        * values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inReal Values to sum.
        * @param optInTimePeriod Window length summed (default 30; range 2..100000;
        *        {@code Integer.MIN_VALUE} selects the default).
        * @param outReal Windowed sum over the period. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#SMA
        */
       public OutRange SUM( int startIdx,
                            int endIdx,
                            float inReal[],
                            int optInTimePeriod,
                            double outReal[] )
       {
          requireIndexRange("SUM", startIdx, endIdx);
          int guardStart = clampedStart("SUM", startIdx, SUM_Lookback(optInTimePeriod));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("SUM", "inReal", inReal, guardInLen);
          requireLength("SUM", "outReal", outReal, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = SUM_Impl(startIdx, endIdx, inReal, optInTimePeriod, outBegIdx, outNBElement, outReal);
          if( retCode != RetCode.Success ) {
             throw failure("SUM", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
    /**** Streaming API *****/

       /**
        * A live SUM stream (unrelated to {@code java.util.stream}): one value per
        * closed bar, bit-identical to {@link Core#SUM} over the same series.
        * Open with {@link Core#sumOpen}; there is no close — the handle is
        * ordinary heap state, unreferenced handles are simply garbage-collected.
        * <p>Concurrency: a handle is single-writer — {@code update}, {@code peek},
        * {@code value} and {@code clone} must not race with an {@code update} on
        * the same handle. With no concurrent {@code update}, {@code peek}/
        * {@code value}/{@code clone} never write the stream and may be called
        * concurrently after safe publication. Independent streams (a
        * {@code clone()} result included) are fully independent.
        * <p>Not serializable by design: to checkpoint, retain the history and
        * re-open — the result is bit-identical by contract.
        */
       public static final class SumStream {
          Core core;
          int optInTimePeriod;
          double periodTotal;
          int ringPos_trailingIdx;
          int ringCap_trailingIdx;
          double[] ring_trailingIdx_inReal;
          double cur_outReal;
          int outRangeBegIdx;
          int outRangeCount;

          SumStream( Core core ) { this.core = core; }

          /**
           * The bars this stream has an output for, in the input series'
           * coordinates: {@code [begIdx, begIdx + count)}.
           * <p>It is what {@link Core#SUM} reports over the same bars: the
           * opener sets it to {@code (lookback, historyLen - lookback)}, every
           * {@code update} adds one to the count — a bar rejected for being
           * non-finite included, because it still happened — {@code peek} leaves
           * it alone, and {@code clone()} carries it verbatim. A plain
           * {@code open} hands back only the last value, a subset of this range,
           * because the caller chose not to take the fill.
           */
          public OutRange outRange() { return new OutRange(outRangeBegIdx, outRangeCount); }

          SumStream( SumStream other ) {
             this.core = other.core;
             this.optInTimePeriod = other.optInTimePeriod;
             this.periodTotal = other.periodTotal;
             this.ringPos_trailingIdx = other.ringPos_trailingIdx;
             this.ringCap_trailingIdx = other.ringCap_trailingIdx;
             this.ring_trailingIdx_inReal = other.ring_trailingIdx_inReal.clone();
             this.cur_outReal = other.cur_outReal;
             this.outRangeBegIdx = other.outRangeBegIdx;
             this.outRangeCount = other.outRangeCount;
          }

          /**
           * Commit one closed bar, returning the new current value.
           * Never allocates handle state.
           * <p>Throws {@link IllegalArgumentException} if any bar value is not
           * finite (NaN or an infinity). That check runs before anything is
           * written, so the state is left exactly as it was: the rejected bar's
           * output is the previous value, held, and {@link #value()} answers it.
           * The stream stays usable, so skip the bar or re-open on a clean
           * history. {@link #outRange()} does advance: the bar happened and
           * occupies a position in the series, so the handle counts it, which is
           * what keeps two handles on one feed aligned when only one rejects.
           * This is the one place the streaming tier is stricter than
           * the batch API, which computes on whatever it is given: a handle
           * retains its state, so a single non-finite bar would poison every
           * later value it produces.
           */
          public double update( double inReal ) {
             if( !Double.isFinite(inReal) ) {
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                throw new TaLibArgumentException("SUM update: BadParam", RetCode.BadParam);
             }
             core.sumStepImpl(this, inReal);
             if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             return this.cur_outReal;
          }

          /**
           * Commit {@code n} closed bars and write their {@code n} values, in one
           * call — exactly {@code n} back-to-back {@code update} calls, with one
           * set of argument checks instead of {@code n}. {@code n} is
           * {@code inReal.length}; the outputs must hold at least that many, and must
           * not be the same array as an input or as each other.
           * <p>{@link #outRange()} counts what this call took in, which is what makes a
           * rejection readable: a non-finite bar {@code k} throws
           * {@link IllegalArgumentException} exactly as {@code update} would, with
           * the bars before {@code k} committed and written, bar {@code k} and
           * everything after it not, and the count advanced by {@code k + 1} —
           * the committed bars plus the rejected one.
           */
          public void updateAndFill( double inReal[], double outReal[] ) {
             requireArgument("SUM updateAndFill", "inReal", inReal);
             requireArgument("SUM updateAndFill", "outReal", outReal);
             final int barCount = inReal.length;
             if( outReal.length < barCount || (Object)outReal == (Object)inReal )
                throw new TaLibArgumentException("SUM updateAndFill: BadParam", RetCode.BadParam);
             for( int i = 0; i < barCount; i++ ) {
                if( !Double.isFinite(inReal[i]) ) {
                   if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                   throw new TaLibArgumentException("SUM updateAndFill: BadParam", RetCode.BadParam);
                }
                core.sumStepImpl(this, inReal[i]);
                outReal[i] = this.cur_outReal;
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             }
          }

          /**
           * Evaluate a forming bar without committing — bit-identical to what the
           * next {@code update} with the same bar would return — the same
           * transition, with every store it would make carried in a local instead.
           * Never writes this handle, so peeks may
           * run concurrently with each other. It copies nothing: the frame runs against this handle, reading its
           * buffers and storing what the step would commit into locals, so the cost
           * does not grow with the period and {@code peek} never allocates.
           */
          public double peek( double inReal ) {
             if( !Double.isFinite(inReal) )
                throw new TaLibArgumentException("SUM peek: BadParam", RetCode.BadParam);
             SumStream sp = this;
             double tempReal = 0.0;
             double cur_outReal = sp.cur_outReal;
             double periodTotal = sp.periodTotal;
             int pkSlot0 = -1;
             double pkVal0 = 0.0;
             if( sp.ringCap_trailingIdx == 0 ) {
                pkSlot0 = 0;
                pkVal0 = inReal;
             }
             periodTotal += inReal;
             tempReal = periodTotal;
             periodTotal -= (sp.ringPos_trailingIdx != pkSlot0) ? sp.ring_trailingIdx_inReal[sp.ringPos_trailingIdx] : pkVal0;
             cur_outReal = tempReal;
             return cur_outReal;
          }

          /**
           * The value at the last bar this stream counted — the bar
           * {@link #outRange()} ends on. The last history bar right after open,
           * then whatever the latest accepted {@code update} returned.
           * A pure field read; {@code peek} does not change it.
           */
          public double value() {
             return this.cur_outReal;
          }

          /**
           * An independent fork of this stream: both evolve separately from here
           * on. Buffers are copied and sub-streams cloned recursively; the
           * {@link Core} reference is shared, since a {@code Core} is immutable
           * for a stream's lifetime.
           *
           * <p>Not the {@code Cloneable} protocol: this calls a copy constructor,
           * never {@code super.clone()}, so it throws nothing.
           *
           * @return an independent stream at the same bar
           */
          @Override
          public SumStream clone() {
             return new SumStream(this);
          }
       }
       void sumStepImpl( SumStream sp, double inReal )
       {
          double tempReal = 0.0;
          if( sp.ringCap_trailingIdx == 0 ) {
             sp.ring_trailingIdx_inReal[0] = inReal;
          }
          sp.periodTotal += inReal;
          tempReal = sp.periodTotal;
          sp.periodTotal -= sp.ring_trailingIdx_inReal[sp.ringPos_trailingIdx];
          sp.cur_outReal = tempReal;
          sp.ring_trailingIdx_inReal[sp.ringPos_trailingIdx] = inReal;
          sp.ringPos_trailingIdx = sp.ringPos_trailingIdx + 1;
          if( sp.ringPos_trailingIdx >= sp.ringCap_trailingIdx ) {
             sp.ringPos_trailingIdx = 0;
          }
       }
       private RetCode sumOpenImpl( SumStream sp, double inReal[], int startIdx, int optInTimePeriod, MInteger outBegIdx, MInteger outNBElement, double outReal[], int outStride )
       {
          double periodTotal = 0;
          double tempReal = 0;
          int i = 0;
          int outIdx = 0;
          int trailingIdx = 0;
          int lookbackTotal = 0;
          int historyLen = inReal.length;
          int endIdx = historyLen - 1;
          if( historyLen < 1 ) {
             return RetCode.OutOfRangeStartIndex;
          }
          if( historyLen > MAX_INDEX + 1 ) {
             return RetCode.OutOfRangeEndIndex;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 30;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.InsufficientHistory;
          }
          /* Identify the minimum number of price bar needed
           * to calculate at least one output.
           */
          lookbackTotal = optInTimePeriod - 1;
          /* Move up the start index if there is not
           * enough initial data.
           */
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.InsufficientHistory ;
          }
          /* Do the MA calculation using tight loops. */
          /* Add-up the initial period, except for the last value. */
          periodTotal = 0;
          trailingIdx = startIdx - lookbackTotal;
          i = trailingIdx;
          if( optInTimePeriod > 1 ) {
             while( i < startIdx ) {
                periodTotal += inReal[i++];
             }
          }
          /* Proceed with the calculation for the requested range.
           * Note that this algorithm allows the inReal and
           * outReal to be the same buffer.
           */
          outIdx = 0;
          do {
             periodTotal += inReal[i++];
             tempReal = periodTotal;
             periodTotal -= inReal[trailingIdx++];
             outReal[outIdx++ * outStride] = tempReal;
          } while( i <= endIdx );
          /* All done. Indicate the output limits and return. */
          outNBElement.value = outIdx;
          outBegIdx.value = startIdx;
          /* Capture the live batch state into the handle. */
          int cap_trailingIdx = i - trailingIdx;
          if( cap_trailingIdx < 0 || cap_trailingIdx > historyLen ) {
             return RetCode.InternalError;
          }
          int allocN_trailingIdx = (cap_trailingIdx > 0)? cap_trailingIdx : 1;
          double[] capRing_trailingIdx_inReal = new double[allocN_trailingIdx];
          System.arraycopy(inReal, historyLen - cap_trailingIdx, capRing_trailingIdx_inReal, 0, cap_trailingIdx);
          sp.optInTimePeriod = optInTimePeriod;
          sp.periodTotal = periodTotal;
          sp.ringPos_trailingIdx = 0;
          sp.ringCap_trailingIdx = cap_trailingIdx;
          sp.ring_trailingIdx_inReal = capRing_trailingIdx_inReal;
          sp.cur_outReal = outReal[(outNBElement.value - 1) * outStride];
          return RetCode.Success;
       }
       /* sumOpenAndFill anchored at startIdx — the composed-open fusion seam. */
       SumStream sumOpenAndFillInternal( double inReal[], int startIdx, int optInTimePeriod, MInteger outBegIdx, MInteger outNBElement, double outReal[] )
       {
          SumStream sp = new SumStream(this);
          RetCode retCode = sumOpenImpl(sp, inReal, startIdx, optInTimePeriod, outBegIdx, outNBElement, outReal, 1);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("SUM openAndFill: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("SUM openAndFill: internal error", retCode);
          }
          throw new TaLibArgumentException("SUM openAndFill: " + retCode, retCode);
       }
       /* Internal startIdx-anchored open behind sumOpen (composition seam). */
       SumStream sumOpenInternal( double inReal[], int startIdx, int optInTimePeriod )
       {
          SumStream sp = new SumStream(this);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          double[] sink_outReal = new double[1];
          RetCode retCode = sumOpenImpl(sp, inReal, startIdx, optInTimePeriod, outBegIdx, outNBElement, sink_outReal, 0);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("SUM open: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("SUM open: internal error", retCode);
          }
          throw new TaLibArgumentException("SUM open: " + retCode, retCode);
       }
       /**
        * Open a live SUM stream over the warm-up history; the handle's
        * {@code value()} starts at the last history bar's value — bit-identical
        * to {@link Core#SUM} at that bar.
        * <p>The history must hold at least {@code SUM_Lookback(...) + 1} bars
        * (unstable-period aware), or {@link InsufficientHistoryException} is
        * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
        * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
        * default, as in the batch API). An EMPTY history throws
        * {@link IndexOutOfBoundsException} — its implied {@code startIdx} of 0
        * names no bar — and a null argument {@link IllegalArgumentException},
        * both ahead of everything above.
        */
       public SumStream sumOpen( double inReal[], int optInTimePeriod )
       {
          requireArgument("SUM open", "inReal", inReal);
          requireHistory("SUM open", inReal.length);
          return sumOpenInternal(inReal, 0, optInTimePeriod);
       }
       /**
        * {@link Core#sumOpen} that also fills the output array(s) bit-identically
        * to {@link Core#SUM} over the whole history in the same single pass
        * (no separate batch call needed for the warm-up plot). Output arrays must
        * not alias the inputs or each other, and must hold
        * {@code historyLen - lookback} values — both checked before anything is
        * written, so an undersized array is an {@link IllegalArgumentException}
        * naming it rather than a fault from inside the fill.
        * <p>The range written is on the returned handle:
        * {@link SumStream#outRange()}.
        */
       public SumStream sumOpenAndFill( double inReal[], int optInTimePeriod, double outReal[] )
       {
          requireArgument("SUM openAndFill", "inReal", inReal);
          requireHistory("SUM openAndFill", inReal.length);
          int guardOutLen = openFillCount("SUM openAndFill", inReal.length, SUM_Lookback(optInTimePeriod));
          requireLength("SUM openAndFill", "outReal", outReal, guardOutLen);
          if( (Object)outReal == (Object)inReal ) {
             throw new TaLibArgumentException("SUM openAndFill: " + RetCode.BadParam, RetCode.BadParam);
          }
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          return sumOpenAndFillInternal(inReal, 0, optInTimePeriod, outBegIdx, outNBElement, outReal);
       }
    /* List of contributors:
     *
     *  Initial  Name/description
     *  -------------------------------------------------------------------
     *  MF       Mario Fortier
     *  CC       Claude Code (AI assistant)
     *
     * Change history:
     *
     *  MMDDYY BY     Description
     *  -------------------------------------------------------------------
     *  090126 MF,CC  First version (issue #272).
     */

       /**
        * Number of leading input bars {@link Core#SUPERTREND} consumes before it
        * can produce its first value.
        * <p>Equivalently, the index of the first bar with a value when the whole
        * series is requested. Feed at least {@code lookback + 1} bars to get any
        * output.
        *
        * @param optInTimePeriod Smoothing period of the Average True Range (default
        *        10; range 2..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInMultiplier Multiplier applied to the Average True Range to set
        *        the band width (default 3; minimum 0; {@code -4e37} selects the default).
        * @return The lookback, or {@code -1} if a parameter is out of range.
        */
       public int SUPERTREND_Lookback( int optInTimePeriod, double optInMultiplier )
       {
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 10;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return -1;
          }
          if( optInMultiplier == REAL_DEFAULT ) {
             optInMultiplier = 3e0;
          } else if( !(optInMultiplier >= 0e0 && optInMultiplier <= REAL_MAX) ) {
             return -1;
          }
          /* Every output bar needs the Average True Range at the same bar, and nothing
           * else reaches further back, so the lookback is exactly the callee's. Never
           * restated here, which is what makes SUPERTREND inherit TA_FUNC_UNST_ATR.
           */
          return ATR_Lookback(optInTimePeriod) ;

       }
       RetCode SUPERTREND_Impl( int startIdx,
                                int endIdx,
                                double inHigh[],
                                double inLow[],
                                double inClose[],
                                int optInTimePeriod,
                                double optInMultiplier,
                                MInteger outBegIdx,
                                MInteger outNBElement,
                                double outReal[],
                                int outInteger[] )
       {
          int i = 0;
          int today = 0;
          int outIdx = 0;
          int lookbackTotal = 0;
          int isUptrend = 0;
          double prevATR = 0;
          double periodTotal = 0;
          double val2 = 0;
          double val3 = 0;
          double greatest = 0;
          double tempCY = 0;
          double tempLT = 0;
          double tempHT = 0;
          double medianPrice = 0;
          double band = 0;
          double basicUpper = 0;
          double basicLower = 0;
          double finalUpper = 0;
          double finalLower = 0;
          double closeToday = 0;
          double prevClose = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 10;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInMultiplier == REAL_DEFAULT ) {
             optInMultiplier = 3e0;
          } else if( !(optInMultiplier >= 0e0 && optInMultiplier <= REAL_MAX) ) {
             return RetCode.BadParam;
          }
          outBegIdx.value = 0;
          outNBElement.value = 0;
          lookbackTotal = SUPERTREND_Lookback(optInTimePeriod, optInMultiplier);
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             return RetCode.Success ;
          }
          /* The Average True Range is carried inline rather than taken from a call,
           * because the band and the ratchet advance together one bar at a time and a
           * whole-range buffer between them would not stream.
           *
           * The arithmetic order below is the bit-exactness contract with TA_ATR (do
           * not reorder or fuse operations): True Range from high-low, then the two
           * previous-close distances in that order; the seed summed from 0.0 over the
           * first 'period' True Ranges and divided once; Wilder smoothing as three
           * separate statements.
           */
          today = startIdx - lookbackTotal + 1;
          periodTotal = 0.0;
          i = optInTimePeriod;
          while( i-- > 0 ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             periodTotal += greatest;
             today += 1;
          }
          prevATR = periodTotal / optInTimePeriod;
          /* Skip the Average True Range's unstable period. Taking the count from the
           * lookback rather than naming the setting keeps the two from disagreeing.
           */
          i = lookbackTotal - optInTimePeriod;
          while( i != 0 ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             today += 1;
             i -= 1;
          }
          /* The first bar has no band to ratchet against and no trend to carry, so
           * both bands take their unclamped value and the trend is seeded long, as
           * ta4j's SuperTrendIndicator does. The formula does not settle this and the
           * published implementations are split on it, so the choice is a convention:
           * it stays visible for as long as the first trend lasts, and on a series
           * whose close never leaves the band it never washes out at all.
           */
          medianPrice = (inHigh[startIdx] + inLow[startIdx]) / 2.0;
          band = optInMultiplier * prevATR;
          finalUpper = medianPrice + band;
          finalLower = medianPrice - band;
          isUptrend = 1;
          prevClose = inClose[startIdx];
          outReal[0] = finalLower;
          outInteger[0] = 1;
          outIdx = 1;
          today = startIdx + 1;
          while( today <= endIdx ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             medianPrice = (tempHT + tempLT) / 2.0;
             band = optInMultiplier * prevATR;
             basicUpper = medianPrice + band;
             basicLower = medianPrice - band;
             /* Each band ratchets toward price and is released only by a close on its
              * far side. Nothing keeps the two ordered -- each is released by its own
              * condition, so the lower one can end up above the upper one -- and where
              * that happens a flip puts the emitted band on the far side of the close.
              * The line is therefore NOT monotone within a trend, and the flag does not
              * always say which side of the line price is on; both read as invariants
              * and neither is one.
              */
             if( basicUpper < finalUpper || prevClose > finalUpper ) {
                finalUpper = basicUpper;
             }
             if( basicLower > finalLower || prevClose < finalLower ) {
                finalLower = basicLower;
             }
             closeToday = inClose[today];
             /* The trend is carried in its own variable rather than recovered by
              * comparing the previous output against the previous bands. The two
              * carried bands do coincide on some bars -- always on a bar with no true
              * range, and on some of them at a multiplier of zero -- and there that
              * comparison cannot tell them apart, so it would silently lose the
              * hysteresis on exactly the flat input a corpus of real prices lacks.
              */
             if( (isUptrend) != 0 ) {
                if( closeToday < finalLower ) {
                   isUptrend = 0;
                }
             } else if( closeToday > finalUpper ) {
                isUptrend = 1;
             }
             if( (isUptrend) != 0 ) {
                outReal[outIdx] = finalLower;
                outInteger[outIdx] = 1;
             } else {
                outReal[outIdx] = finalUpper;
                outInteger[outIdx] = 0 - 1;
             }
             prevClose = closeToday;
             outIdx += 1;
             today += 1;
          }
          outBegIdx.value = startIdx;
          outNBElement.value = outIdx;
          return RetCode.Success ;
       }
       RetCode SUPERTREND_Impl( int startIdx,
                                int endIdx,
                                float inHigh[],
                                float inLow[],
                                float inClose[],
                                int optInTimePeriod,
                                double optInMultiplier,
                                MInteger outBegIdx,
                                MInteger outNBElement,
                                double outReal[],
                                int outInteger[] )
       {
          int i = 0;
          int today = 0;
          int outIdx = 0;
          int lookbackTotal = 0;
          int isUptrend = 0;
          double prevATR = 0;
          double periodTotal = 0;
          double val2 = 0;
          double val3 = 0;
          double greatest = 0;
          double tempCY = 0;
          double tempLT = 0;
          double tempHT = 0;
          double medianPrice = 0;
          double band = 0;
          double basicUpper = 0;
          double basicLower = 0;
          double finalUpper = 0;
          double finalLower = 0;
          double closeToday = 0;
          double prevClose = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 10;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInMultiplier == REAL_DEFAULT ) {
             optInMultiplier = 3e0;
          } else if( !(optInMultiplier >= 0e0 && optInMultiplier <= REAL_MAX) ) {
             return RetCode.BadParam;
          }
          outBegIdx.value = 0;
          outNBElement.value = 0;
          lookbackTotal = SUPERTREND_Lookback(optInTimePeriod, optInMultiplier);
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          if( startIdx > endIdx ) {
             return RetCode.Success ;
          }
          today = startIdx - lookbackTotal + 1;
          periodTotal = 0.0;
          i = optInTimePeriod;
          while( i-- > 0 ) {
             tempLT = (double)inLow[today];
             tempHT = (double)inHigh[today];
             tempCY = (double)inClose[today - 1];
             greatest = tempHT - tempLT;
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             periodTotal += greatest;
             today += 1;
          }
          prevATR = periodTotal / optInTimePeriod;
          i = lookbackTotal - optInTimePeriod;
          while( i != 0 ) {
             tempLT = (double)inLow[today];
             tempHT = (double)inHigh[today];
             tempCY = (double)inClose[today - 1];
             greatest = tempHT - tempLT;
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             today += 1;
             i -= 1;
          }
          medianPrice = ((double)inHigh[startIdx] + (double)inLow[startIdx]) / 2.0;
          band = optInMultiplier * prevATR;
          finalUpper = medianPrice + band;
          finalLower = medianPrice - band;
          isUptrend = 1;
          prevClose = (double)inClose[startIdx];
          outReal[0] = finalLower;
          outInteger[0] = 1;
          outIdx = 1;
          today = startIdx + 1;
          while( today <= endIdx ) {
             tempLT = (double)inLow[today];
             tempHT = (double)inHigh[today];
             tempCY = (double)inClose[today - 1];
             greatest = tempHT - tempLT;
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             medianPrice = (tempHT + tempLT) / 2.0;
             band = optInMultiplier * prevATR;
             basicUpper = medianPrice + band;
             basicLower = medianPrice - band;
             if( basicUpper < finalUpper || prevClose > finalUpper ) {
                finalUpper = basicUpper;
             }
             if( basicLower > finalLower || prevClose < finalLower ) {
                finalLower = basicLower;
             }
             closeToday = (double)inClose[today];
             if( (isUptrend) != 0 ) {
                if( closeToday < finalLower ) {
                   isUptrend = 0;
                }
             } else if( closeToday > finalUpper ) {
                isUptrend = 1;
             }
             if( (isUptrend) != 0 ) {
                outReal[outIdx] = finalLower;
                outInteger[outIdx] = 1;
             } else {
                outReal[outIdx] = finalUpper;
                outInteger[outIdx] = 0 - 1;
             }
             prevClose = closeToday;
             outIdx += 1;
             today += 1;
          }
          outBegIdx.value = startIdx;
          outNBElement.value = outIdx;
          return RetCode.Success ;
       }
       /**
        * An ATR-scaled trailing band that follows price on one side at a time and
        * flips to the other side when the close breaks through it. The trend rides
        * the lower band while it is up and the upper band while it is down, so the
        * line is usually below price in an uptrend and above it in a downtrend, and
        * the flip is the signal. Attributed to Olivier Seban.
        * <p><b>Formula</b>
        * <pre>{@code
        * Median = (High + Low) / 2
        * BasicUpper = Median + Multiplier * ATR(TimePeriod)
        * BasicLower = Median - Multiplier * ATR(TimePeriod)
        * Upper = BasicUpper, when BasicUpper < previous Upper or previous Close > previous Upper; otherwise the previous Upper
        * Lower = BasicLower, when BasicLower > previous Lower or previous Close < previous Lower; otherwise the previous Lower
        * SuperTrend = Lower while the trend is up, until Close < Lower flips it down
        * SuperTrend = Upper while the trend is down, until Close > Upper flips it up
        * }</pre>
        * <p><b>Notes</b>
        * <ul>
        * <li>Both bands are carried forward on every bar, and the trend is decided against the current bar's band. This is the form Investopedia, TradingView and ta4j all describe. A second published form, from the AmiBroker script attributed to Seban, carries only the band the trend is riding and lets the other float free; the two agree on almost every bar and part company at a flip, where this form hands back a band it has been carrying all along and that one hands back a fresh value.</li>
        * <li>The recurrence has no value before the first bar it can be computed on, so the trend is seeded up there and both bands take their unclamped value. Published implementations are split on that seed; this is ta4j's. The choice stays visible for as long as the first trend lasts, it never washes out on a series whose close never leaves the band, and it is why the same bar computed from a later start index can differ.</li>
        * <li>The direction is reported as +1 for an uptrend and -1 for a downtrend, the sign every other signed output in this library uses for bullish. TradingView's built-in {@code ta.supertrend} returns the opposite signs for the same two states, and seeds the other way; a strategy ported from Pine has to swap them.</li>
        * <li>The two carried bands are released by different conditions, so nothing keeps the lower one below the upper one. Where they cross, a flip leaves the line on the far side of the close, and within a single trend the line can widen away from price instead of tightening toward it. Both are ordinary consequences of the published formula, not a variation on it; they are simply not the guarantees the indicator is usually described as giving.</li>
        * <li>A multiplier of zero is degenerate but defined: the two basic bands collapse onto the median price exactly. The carried bands do not collapse with them — each is still released by its own condition — so they coincide on some bars and differ on others, and the trend flips on most bars rather than on every one.</li>
        * <li>The band inherits the Average True Range's warm-up, so a caller who wants it converged sets {@code TA_FUNC_UNST_ATR}, exactly as when calling that function directly.</li>
        * </ul>
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#SUPERTREND_Lookback} is a <b>success
        * with no values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inHigh High price of each bar.
        * @param inLow Low price of each bar.
        * @param inClose Close price of each bar.
        * @param optInTimePeriod Smoothing period of the Average True Range (default
        *        10; range 2..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInMultiplier Multiplier applied to the Average True Range to set
        *        the band width (default 3; minimum 0; {@code -4e37} selects the default).
        * @param outReal The SuperTrend line: the band the trend is currently
        *        riding. Must hold at least {@code endIdx - startIdx + 1} values.
        * @param outInteger Trend direction: +1 while the trend rides the lower
        *        band, -1 while it rides the upper one. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#ATR
        * @see Core#MEDPRICE
        * @see Core#SAR
        * @see Core#SAREXT
        * @see Core#KC
        */
       public OutRange SUPERTREND( int startIdx,
                                   int endIdx,
                                   double inHigh[],
                                   double inLow[],
                                   double inClose[],
                                   int optInTimePeriod,
                                   double optInMultiplier,
                                   double outReal[],
                                   int outInteger[] )
       {
          requireIndexRange("SUPERTREND", startIdx, endIdx);
          int guardStart = clampedStart("SUPERTREND", startIdx, SUPERTREND_Lookback(optInTimePeriod, optInMultiplier));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("SUPERTREND", "inHigh", inHigh, guardInLen);
          requireLength("SUPERTREND", "inLow", inLow, guardInLen);
          requireLength("SUPERTREND", "inClose", inClose, guardInLen);
          requireLength("SUPERTREND", "outReal", outReal, guardOutLen);
          requireLength("SUPERTREND", "outInteger", outInteger, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = SUPERTREND_Impl(startIdx, endIdx, inHigh, inLow, inClose, optInTimePeriod, optInMultiplier, outBegIdx, outNBElement, outReal, outInteger);
          if( retCode != RetCode.Success ) {
             throw failure("SUPERTREND", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
       /**
        * An ATR-scaled trailing band that follows price on one side at a time and
        * flips to the other side when the close breaks through it. The trend rides
        * the lower band while it is up and the upper band while it is down, so the
        * line is usually below price in an uptrend and above it in a downtrend, and
        * the flip is the signal. Attributed to Olivier Seban.
        * <p><b>Formula</b>
        * <pre>{@code
        * Median = (High + Low) / 2
        * BasicUpper = Median + Multiplier * ATR(TimePeriod)
        * BasicLower = Median - Multiplier * ATR(TimePeriod)
        * Upper = BasicUpper, when BasicUpper < previous Upper or previous Close > previous Upper; otherwise the previous Upper
        * Lower = BasicLower, when BasicLower > previous Lower or previous Close < previous Lower; otherwise the previous Lower
        * SuperTrend = Lower while the trend is up, until Close < Lower flips it down
        * SuperTrend = Upper while the trend is down, until Close > Upper flips it up
        * }</pre>
        * <p><b>Notes</b>
        * <ul>
        * <li>Both bands are carried forward on every bar, and the trend is decided against the current bar's band. This is the form Investopedia, TradingView and ta4j all describe. A second published form, from the AmiBroker script attributed to Seban, carries only the band the trend is riding and lets the other float free; the two agree on almost every bar and part company at a flip, where this form hands back a band it has been carrying all along and that one hands back a fresh value.</li>
        * <li>The recurrence has no value before the first bar it can be computed on, so the trend is seeded up there and both bands take their unclamped value. Published implementations are split on that seed; this is ta4j's. The choice stays visible for as long as the first trend lasts, it never washes out on a series whose close never leaves the band, and it is why the same bar computed from a later start index can differ.</li>
        * <li>The direction is reported as +1 for an uptrend and -1 for a downtrend, the sign every other signed output in this library uses for bullish. TradingView's built-in {@code ta.supertrend} returns the opposite signs for the same two states, and seeds the other way; a strategy ported from Pine has to swap them.</li>
        * <li>The two carried bands are released by different conditions, so nothing keeps the lower one below the upper one. Where they cross, a flip leaves the line on the far side of the close, and within a single trend the line can widen away from price instead of tightening toward it. Both are ordinary consequences of the published formula, not a variation on it; they are simply not the guarantees the indicator is usually described as giving.</li>
        * <li>A multiplier of zero is degenerate but defined: the two basic bands collapse onto the median price exactly. The carried bands do not collapse with them — each is still released by its own condition — so they coincide on some bars and differ on others, and the trend flips on most bars rather than on every one.</li>
        * <li>The band inherits the Average True Range's warm-up, so a caller who wants it converged sets {@code TA_FUNC_UNST_ATR}, exactly as when calling that function directly.</li>
        * </ul>
        * <p>This is the {@code float[]} overload. The arithmetic is performed in
        * {@code double} before being written to the {@code double[]} output, so a
        * result beyond {@code float} range is still representable.
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#SUPERTREND_Lookback} is a <b>success
        * with no values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inHigh High price of each bar.
        * @param inLow Low price of each bar.
        * @param inClose Close price of each bar.
        * @param optInTimePeriod Smoothing period of the Average True Range (default
        *        10; range 2..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInMultiplier Multiplier applied to the Average True Range to set
        *        the band width (default 3; minimum 0; {@code -4e37} selects the default).
        * @param outReal The SuperTrend line: the band the trend is currently
        *        riding. Must hold at least {@code endIdx - startIdx + 1} values.
        * @param outInteger Trend direction: +1 while the trend rides the lower
        *        band, -1 while it rides the upper one. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#ATR
        * @see Core#MEDPRICE
        * @see Core#SAR
        * @see Core#SAREXT
        * @see Core#KC
        */
       public OutRange SUPERTREND( int startIdx,
                                   int endIdx,
                                   float inHigh[],
                                   float inLow[],
                                   float inClose[],
                                   int optInTimePeriod,
                                   double optInMultiplier,
                                   double outReal[],
                                   int outInteger[] )
       {
          requireIndexRange("SUPERTREND", startIdx, endIdx);
          int guardStart = clampedStart("SUPERTREND", startIdx, SUPERTREND_Lookback(optInTimePeriod, optInMultiplier));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("SUPERTREND", "inHigh", inHigh, guardInLen);
          requireLength("SUPERTREND", "inLow", inLow, guardInLen);
          requireLength("SUPERTREND", "inClose", inClose, guardInLen);
          requireLength("SUPERTREND", "outReal", outReal, guardOutLen);
          requireLength("SUPERTREND", "outInteger", outInteger, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = SUPERTREND_Impl(startIdx, endIdx, inHigh, inLow, inClose, optInTimePeriod, optInMultiplier, outBegIdx, outNBElement, outReal, outInteger);
          if( retCode != RetCode.Success ) {
             throw failure("SUPERTREND", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
    /**** Streaming API *****/

       /**
        * A live SUPERTREND stream (unrelated to {@code java.util.stream}): one value per
        * closed bar, bit-identical to {@link Core#SUPERTREND} over the same series.
        * Open with {@link Core#supertrendOpen}; there is no close — the handle is
        * ordinary heap state, unreferenced handles are simply garbage-collected.
        * <p>Concurrency: a handle is single-writer — {@code update}, {@code peek},
        * {@code value} and {@code clone} must not race with an {@code update} on
        * the same handle. With no concurrent {@code update}, {@code peek}/
        * {@code value}/{@code clone} never write the stream and may be called
        * concurrently after safe publication. Independent streams (a
        * {@code clone()} result included) are fully independent.
        * <p>Not serializable by design: to checkpoint, retain the history and
        * re-open — the result is bit-identical by contract.
        */
       public static final class SupertrendStream {
          Core core;
          int optInTimePeriod;
          double optInMultiplier;
          int isUptrend;
          double prevATR;
          double finalUpper;
          double finalLower;
          double prevClose;
          double lag1_inClose;
          double cur_outReal;
          int cur_outInteger;
          int outRangeBegIdx;
          int outRangeCount;

          SupertrendStream( Core core ) { this.core = core; }

          /**
           * The bars this stream has an output for, in the input series'
           * coordinates: {@code [begIdx, begIdx + count)}.
           * <p>It is what {@link Core#SUPERTREND} reports over the same bars: the
           * opener sets it to {@code (lookback, historyLen - lookback)}, every
           * {@code update} adds one to the count — a bar rejected for being
           * non-finite included, because it still happened — {@code peek} leaves
           * it alone, and {@code clone()} carries it verbatim. A plain
           * {@code open} hands back only the last value, a subset of this range,
           * because the caller chose not to take the fill.
           */
          public OutRange outRange() { return new OutRange(outRangeBegIdx, outRangeCount); }

          SupertrendStream( SupertrendStream other ) {
             this.core = other.core;
             this.optInTimePeriod = other.optInTimePeriod;
             this.optInMultiplier = other.optInMultiplier;
             this.isUptrend = other.isUptrend;
             this.prevATR = other.prevATR;
             this.finalUpper = other.finalUpper;
             this.finalLower = other.finalLower;
             this.prevClose = other.prevClose;
             this.lag1_inClose = other.lag1_inClose;
             this.cur_outReal = other.cur_outReal;
             this.cur_outInteger = other.cur_outInteger;
             this.outRangeBegIdx = other.outRangeBegIdx;
             this.outRangeCount = other.outRangeCount;
          }

          /**
           * Commit one closed bar, writing the new current values into the {@code out} the CALLER owns.
           * Never allocates handle state.
           * <p>Throws {@link IllegalArgumentException} if any bar value is not
           * finite (NaN or an infinity). That check runs before anything is
           * written, so the state is left exactly as it was: the rejected bar's
           * output is the previous value, held, and {@link #value(SupertrendOut)} answers it.
           * The stream stays usable, so skip the bar or re-open on a clean
           * history. {@link #outRange()} does advance: the bar happened and
           * occupies a position in the series, so the handle counts it, which is
           * what keeps two handles on one feed aligned when only one rejects.
           * This is the one place the streaming tier is stricter than
           * the batch API, which computes on whatever it is given: a handle
           * retains its state, so a single non-finite bar would poison every
           * later value it produces.
           */
          public void update( double inHigh, double inLow, double inClose, SupertrendOut out ) {
             requireArgument("SUPERTREND update", "out", out);
             if( !Double.isFinite(inHigh) || !Double.isFinite(inLow) || !Double.isFinite(inClose) ) {
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                throw new TaLibArgumentException("SUPERTREND update: BadParam", RetCode.BadParam);
             }
             core.supertrendStepImpl(this, inHigh, inLow, inClose);
             if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             out.real = this.cur_outReal;
             out.integer = this.cur_outInteger;
          }

          /**
           * Commit {@code n} closed bars and write their {@code n} values, in one
           * call — exactly {@code n} back-to-back {@code update} calls, with one
           * set of argument checks instead of {@code n}. {@code n} is
           * {@code inHigh.length}; the outputs must hold at least that many, and must
           * not be the same array as an input or as each other.
           * <p>{@link #outRange()} counts what this call took in, which is what makes a
           * rejection readable: a non-finite bar {@code k} throws
           * {@link IllegalArgumentException} exactly as {@code update} would, with
           * the bars before {@code k} committed and written, bar {@code k} and
           * everything after it not, and the count advanced by {@code k + 1} —
           * the committed bars plus the rejected one.
           */
          public void updateAndFill( double inHigh[], double inLow[], double inClose[], double outReal[], int outInteger[] ) {
             requireArgument("SUPERTREND updateAndFill", "inHigh", inHigh);
             requireArgument("SUPERTREND updateAndFill", "inLow", inLow);
             requireArgument("SUPERTREND updateAndFill", "inClose", inClose);
             requireArgument("SUPERTREND updateAndFill", "outReal", outReal);
             requireArgument("SUPERTREND updateAndFill", "outInteger", outInteger);
             final int barCount = inHigh.length;
             if( inLow.length != barCount || inClose.length != barCount || outReal.length < barCount || outInteger.length < barCount || (Object)outReal == (Object)inHigh || (Object)outReal == (Object)inLow || (Object)outReal == (Object)inClose || (Object)outInteger == (Object)inHigh || (Object)outInteger == (Object)inLow || (Object)outInteger == (Object)inClose || (Object)outReal == (Object)outInteger )
                throw new TaLibArgumentException("SUPERTREND updateAndFill: BadParam", RetCode.BadParam);
             for( int i = 0; i < barCount; i++ ) {
                if( !Double.isFinite(inHigh[i]) || !Double.isFinite(inLow[i]) || !Double.isFinite(inClose[i]) ) {
                   if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                   throw new TaLibArgumentException("SUPERTREND updateAndFill: BadParam", RetCode.BadParam);
                }
                core.supertrendStepImpl(this, inHigh[i], inLow[i], inClose[i]);
                outReal[i] = this.cur_outReal;
                outInteger[i] = this.cur_outInteger;
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             }
          }

          /**
           * Evaluate a forming bar without committing — bit-identical to what the
           * next {@code update} with the same bar would write — the same
           * transition, with every store it would make carried in a local instead.
           * Never writes this handle, so peeks may
           * run concurrently with each other. It copies nothing: the frame runs against this handle, reading its
           * buffers and storing what the step would commit into locals, so the cost
           * does not grow with the period and {@code peek} never allocates.
           */
          public void peek( double inHigh, double inLow, double inClose, SupertrendOut out ) {
             requireArgument("SUPERTREND peek", "out", out);
             if( !Double.isFinite(inHigh) || !Double.isFinite(inLow) || !Double.isFinite(inClose) )
                throw new TaLibArgumentException("SUPERTREND peek: BadParam", RetCode.BadParam);
             SupertrendStream sp = this;
             double val2 = 0.0;
             double val3 = 0.0;
             double greatest = 0.0;
             double tempCY = 0.0;
             double tempLT = 0.0;
             double tempHT = 0.0;
             double medianPrice = 0.0;
             double band = 0.0;
             double basicUpper = 0.0;
             double basicLower = 0.0;
             double closeToday = 0.0;
             int cur_outInteger = sp.cur_outInteger;
             double cur_outReal = sp.cur_outReal;
             double finalLower = sp.finalLower;
             double finalUpper = sp.finalUpper;
             int isUptrend = sp.isUptrend;
             double prevATR = sp.prevATR;
             tempLT = inLow;
             tempHT = inHigh;
             tempCY = sp.lag1_inClose;
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= sp.optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= sp.optInTimePeriod;
             medianPrice = (tempHT + tempLT) / 2.0;
             band = sp.optInMultiplier * prevATR;
             basicUpper = medianPrice + band;
             basicLower = medianPrice - band;
             /* Each band ratchets toward price and is released only by a close on its
              * far side. Nothing keeps the two ordered -- each is released by its own
              * condition, so the lower one can end up above the upper one -- and where
              * that happens a flip puts the emitted band on the far side of the close.
              * The line is therefore NOT monotone within a trend, and the flag does not
              * always say which side of the line price is on; both read as invariants
              * and neither is one.
              */
             if( basicUpper < finalUpper || sp.prevClose > finalUpper ) {
                finalUpper = basicUpper;
             }
             if( basicLower > finalLower || sp.prevClose < finalLower ) {
                finalLower = basicLower;
             }
             closeToday = inClose;
             /* The trend is carried in its own variable rather than recovered by
              * comparing the previous output against the previous bands. The two
              * carried bands do coincide on some bars -- always on a bar with no true
              * range, and on some of them at a multiplier of zero -- and there that
              * comparison cannot tell them apart, so it would silently lose the
              * hysteresis on exactly the flat input a corpus of real prices lacks.
              */
             if( (isUptrend) != 0 ) {
                if( closeToday < finalLower ) {
                   isUptrend = 0;
                }
             } else if( closeToday > finalUpper ) {
                isUptrend = 1;
             }
             if( (isUptrend) != 0 ) {
                cur_outReal = finalLower;
                cur_outInteger = 1;
             } else {
                cur_outReal = finalUpper;
                cur_outInteger = 0 - 1;
             }
             out.real = cur_outReal;
             out.integer = cur_outInteger;
          }

          /**
           * The value at the last bar this stream counted — the bar
           * {@link #outRange()} ends on. The last history bar right after open,
           * then whatever the latest accepted {@code update} wrote.
           * A pure field read; {@code peek} does not change it. Overwrites {@code out}, allocating nothing.
           */
          public void value( SupertrendOut out ) {
             requireArgument("SUPERTREND value", "out", out);
             out.real = this.cur_outReal;
             out.integer = this.cur_outInteger;
          }

          /**
           * An independent fork of this stream: both evolve separately from here
           * on. Buffers are copied and sub-streams cloned recursively; the
           * {@link Core} reference is shared, since a {@code Core} is immutable
           * for a stream's lifetime.
           *
           * <p>Not the {@code Cloneable} protocol: this calls a copy constructor,
           * never {@code super.clone()}, so it throws nothing.
           *
           * @return an independent stream at the same bar
           */
          @Override
          public SupertrendStream clone() {
             return new SupertrendStream(this);
          }
       }

       /**
        * The outputs of one SUPERTREND bar, written by the stream into an object the
        * CALLER owns. Allocate one and reuse it: {@code update}, {@code peek}
        * and {@code value} overwrite its fields, so the sink itself costs
        * nothing per bar.
        *
        * <p><b>Its contents are only valid until the next call that writes it.</b>
        * It is a mutable buffer, not a reading: a reference kept past that call,
        * or one put in a collection, sees the value change underneath it. Copy the
        * fields out if the reading has to outlive the call.
        *
        * <p>Deliberately no {@code equals} or {@code hashCode}: a mutable type
        * with value equality breaks the {@code HashMap}/{@code HashSet}
        * invariant the moment a reused instance becomes a key. Compare the fields.
        */
       public static final class SupertrendOut {
          /** The SuperTrend line: the band the trend is currently riding. */
          public double real;
          /** Trend direction: +1 while the trend rides the lower band, -1 while it rides the upper one. */
          public int integer;
       }
       void supertrendStepImpl( SupertrendStream sp, double inHigh, double inLow, double inClose )
       {
          double val2 = 0.0;
          double val3 = 0.0;
          double greatest = 0.0;
          double tempCY = 0.0;
          double tempLT = 0.0;
          double tempHT = 0.0;
          double medianPrice = 0.0;
          double band = 0.0;
          double basicUpper = 0.0;
          double basicLower = 0.0;
          double closeToday = 0.0;
          tempLT = inLow;
          tempHT = inHigh;
          tempCY = sp.lag1_inClose;
          greatest = tempHT - tempLT;
          /* val1 */
          val2 = Math.abs(tempCY - tempHT);
          if( val2 > greatest ) {
             greatest = val2;
          }
          val3 = Math.abs(tempCY - tempLT);
          if( val3 > greatest ) {
             greatest = val3;
          }
          sp.prevATR *= sp.optInTimePeriod - 1;
          sp.prevATR += greatest;
          sp.prevATR /= sp.optInTimePeriod;
          medianPrice = (tempHT + tempLT) / 2.0;
          band = sp.optInMultiplier * sp.prevATR;
          basicUpper = medianPrice + band;
          basicLower = medianPrice - band;
          /* Each band ratchets toward price and is released only by a close on its
           * far side. Nothing keeps the two ordered -- each is released by its own
           * condition, so the lower one can end up above the upper one -- and where
           * that happens a flip puts the emitted band on the far side of the close.
           * The line is therefore NOT monotone within a trend, and the flag does not
           * always say which side of the line price is on; both read as invariants
           * and neither is one.
           */
          if( basicUpper < sp.finalUpper || sp.prevClose > sp.finalUpper ) {
             sp.finalUpper = basicUpper;
          }
          if( basicLower > sp.finalLower || sp.prevClose < sp.finalLower ) {
             sp.finalLower = basicLower;
          }
          closeToday = inClose;
          /* The trend is carried in its own variable rather than recovered by
           * comparing the previous output against the previous bands. The two
           * carried bands do coincide on some bars -- always on a bar with no true
           * range, and on some of them at a multiplier of zero -- and there that
           * comparison cannot tell them apart, so it would silently lose the
           * hysteresis on exactly the flat input a corpus of real prices lacks.
           */
          if( (sp.isUptrend) != 0 ) {
             if( closeToday < sp.finalLower ) {
                sp.isUptrend = 0;
             }
          } else if( closeToday > sp.finalUpper ) {
             sp.isUptrend = 1;
          }
          if( (sp.isUptrend) != 0 ) {
             sp.cur_outReal = sp.finalLower;
             sp.cur_outInteger = 1;
          } else {
             sp.cur_outReal = sp.finalUpper;
             sp.cur_outInteger = 0 - 1;
          }
          sp.prevClose = closeToday;
          sp.lag1_inClose = inClose;
       }
       private RetCode supertrendOpenImpl( SupertrendStream sp, double inHigh[], double inLow[], double inClose[], int startIdx, int optInTimePeriod, double optInMultiplier, MInteger outBegIdx, MInteger outNBElement, double outReal[], int outInteger[], int outStride )
       {
          int i = 0;
          int today = 0;
          int outIdx = 0;
          int lookbackTotal = 0;
          int isUptrend = 0;
          double prevATR = 0;
          double periodTotal = 0;
          double val2 = 0;
          double val3 = 0;
          double greatest = 0;
          double tempCY = 0;
          double tempLT = 0;
          double tempHT = 0;
          double medianPrice = 0;
          double band = 0;
          double basicUpper = 0;
          double basicLower = 0;
          double finalUpper = 0;
          double finalLower = 0;
          double closeToday = 0;
          double prevClose = 0;
          int historyLen = inHigh.length;
          int endIdx = historyLen - 1;
          if( historyLen < 1 ) {
             return RetCode.OutOfRangeStartIndex;
          }
          if( historyLen > MAX_INDEX + 1 ) {
             return RetCode.OutOfRangeEndIndex;
          }
          if( inLow.length != inHigh.length || inClose.length != inHigh.length ) {
             return RetCode.BadParam;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 10;
          } else if( optInTimePeriod < 2 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInMultiplier == REAL_DEFAULT ) {
             optInMultiplier = 3e0;
          } else if( !(optInMultiplier >= 0e0 && optInMultiplier <= REAL_MAX) ) {
             return RetCode.BadParam;
          }
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.InsufficientHistory;
          }
          outBegIdx.value = 0;
          outNBElement.value = 0;
          lookbackTotal = SUPERTREND_Lookback(optInTimePeriod, optInMultiplier);
          if( startIdx < lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             return RetCode.InsufficientHistory ;
          }
          /* The Average True Range is carried inline rather than taken from a call,
           * because the band and the ratchet advance together one bar at a time and a
           * whole-range buffer between them would not stream.
           *
           * The arithmetic order below is the bit-exactness contract with TA_ATR (do
           * not reorder or fuse operations): True Range from high-low, then the two
           * previous-close distances in that order; the seed summed from 0.0 over the
           * first 'period' True Ranges and divided once; Wilder smoothing as three
           * separate statements.
           */
          today = startIdx - lookbackTotal + 1;
          periodTotal = 0.0;
          i = optInTimePeriod;
          while( i-- > 0 ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             periodTotal += greatest;
             today += 1;
          }
          prevATR = periodTotal / optInTimePeriod;
          /* Skip the Average True Range's unstable period. Taking the count from the
           * lookback rather than naming the setting keeps the two from disagreeing.
           */
          i = lookbackTotal - optInTimePeriod;
          while( i != 0 ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             today += 1;
             i -= 1;
          }
          /* The first bar has no band to ratchet against and no trend to carry, so
           * both bands take their unclamped value and the trend is seeded long, as
           * ta4j's SuperTrendIndicator does. The formula does not settle this and the
           * published implementations are split on it, so the choice is a convention:
           * it stays visible for as long as the first trend lasts, and on a series
           * whose close never leaves the band it never washes out at all.
           */
          medianPrice = (inHigh[startIdx] + inLow[startIdx]) / 2.0;
          band = optInMultiplier * prevATR;
          finalUpper = medianPrice + band;
          finalLower = medianPrice - band;
          isUptrend = 1;
          prevClose = inClose[startIdx];
          outReal[0 * outStride] = finalLower;
          outInteger[0 * outStride] = 1;
          outIdx = 1;
          today = startIdx + 1;
          while( today <= endIdx ) {
             tempLT = inLow[today];
             tempHT = inHigh[today];
             tempCY = inClose[today - 1];
             greatest = tempHT - tempLT;
             /* val1 */
             val2 = Math.abs(tempCY - tempHT);
             if( val2 > greatest ) {
                greatest = val2;
             }
             val3 = Math.abs(tempCY - tempLT);
             if( val3 > greatest ) {
                greatest = val3;
             }
             prevATR *= optInTimePeriod - 1;
             prevATR += greatest;
             prevATR /= optInTimePeriod;
             medianPrice = (tempHT + tempLT) / 2.0;
             band = optInMultiplier * prevATR;
             basicUpper = medianPrice + band;
             basicLower = medianPrice - band;
             /* Each band ratchets toward price and is released only by a close on its
              * far side. Nothing keeps the two ordered -- each is released by its own
              * condition, so the lower one can end up above the upper one -- and where
              * that happens a flip puts the emitted band on the far side of the close.
              * The line is therefore NOT monotone within a trend, and the flag does not
              * always say which side of the line price is on; both read as invariants
              * and neither is one.
              */
             if( basicUpper < finalUpper || prevClose > finalUpper ) {
                finalUpper = basicUpper;
             }
             if( basicLower > finalLower || prevClose < finalLower ) {
                finalLower = basicLower;
             }
             closeToday = inClose[today];
             /* The trend is carried in its own variable rather than recovered by
              * comparing the previous output against the previous bands. The two
              * carried bands do coincide on some bars -- always on a bar with no true
              * range, and on some of them at a multiplier of zero -- and there that
              * comparison cannot tell them apart, so it would silently lose the
              * hysteresis on exactly the flat input a corpus of real prices lacks.
              */
             if( (isUptrend) != 0 ) {
                if( closeToday < finalLower ) {
                   isUptrend = 0;
                }
             } else if( closeToday > finalUpper ) {
                isUptrend = 1;
             }
             if( (isUptrend) != 0 ) {
                outReal[outIdx * outStride] = finalLower;
                outInteger[outIdx * outStride] = 1;
             } else {
                outReal[outIdx * outStride] = finalUpper;
                outInteger[outIdx * outStride] = 0 - 1;
             }
             prevClose = closeToday;
             outIdx += 1;
             today += 1;
          }
          outBegIdx.value = startIdx;
          outNBElement.value = outIdx;
          /* Capture the live batch state into the handle. */
          sp.optInTimePeriod = optInTimePeriod;
          sp.optInMultiplier = optInMultiplier;
          sp.isUptrend = isUptrend;
          sp.prevATR = prevATR;
          sp.finalUpper = finalUpper;
          sp.finalLower = finalLower;
          sp.prevClose = prevClose;
          sp.lag1_inClose = inClose[historyLen - 1];
          sp.cur_outReal = outReal[(outNBElement.value - 1) * outStride];
          sp.cur_outInteger = outInteger[(outNBElement.value - 1) * outStride];
          return RetCode.Success;
       }
       /* supertrendOpenAndFill anchored at startIdx — the composed-open fusion seam. */
       SupertrendStream supertrendOpenAndFillInternal( double inHigh[], double inLow[], double inClose[], int startIdx, int optInTimePeriod, double optInMultiplier, MInteger outBegIdx, MInteger outNBElement, double outReal[], int outInteger[] )
       {
          SupertrendStream sp = new SupertrendStream(this);
          RetCode retCode = supertrendOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, optInMultiplier, outBegIdx, outNBElement, outReal, outInteger, 1);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("SUPERTREND openAndFill: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("SUPERTREND openAndFill: internal error", retCode);
          }
          throw new TaLibArgumentException("SUPERTREND openAndFill: " + retCode, retCode);
       }
       /* Internal startIdx-anchored open behind supertrendOpen (composition seam). */
       SupertrendStream supertrendOpenInternal( double inHigh[], double inLow[], double inClose[], int startIdx, int optInTimePeriod, double optInMultiplier )
       {
          SupertrendStream sp = new SupertrendStream(this);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          double[] sink_outReal = new double[1];
          int[] sink_outInteger = new int[1];
          RetCode retCode = supertrendOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, optInMultiplier, outBegIdx, outNBElement, sink_outReal, sink_outInteger, 0);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("SUPERTREND open: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("SUPERTREND open: internal error", retCode);
          }
          throw new TaLibArgumentException("SUPERTREND open: " + retCode, retCode);
       }
       /**
        * Open a live SUPERTREND stream over the warm-up history; the handle's
        * {@code value()} starts at the last history bar's value — bit-identical
        * to {@link Core#SUPERTREND} at that bar.
        * <p>The history must hold at least {@code SUPERTREND_Lookback(...) + 1} bars
        * (unstable-period aware), or {@link InsufficientHistoryException} is
        * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
        * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
        * default, as in the batch API). An EMPTY history throws
        * {@link IndexOutOfBoundsException} — its implied {@code startIdx} of 0
        * names no bar — and a null argument {@link IllegalArgumentException},
        * both ahead of everything above.
        */
       public SupertrendStream supertrendOpen( double inHigh[], double inLow[], double inClose[], int optInTimePeriod, double optInMultiplier )
       {
          requireArgument("SUPERTREND open", "inHigh", inHigh);
          requireHistory("SUPERTREND open", inHigh.length);
          requireArgument("SUPERTREND open", "inLow", inLow);
          requireArgument("SUPERTREND open", "inClose", inClose);
          requireHistoryLength("SUPERTREND open", "inLow", inLow.length, inHigh.length);
          requireHistoryLength("SUPERTREND open", "inClose", inClose.length, inHigh.length);
          return supertrendOpenInternal(inHigh, inLow, inClose, 0, optInTimePeriod, optInMultiplier);
       }
       /**
        * {@link Core#supertrendOpen} that also fills the output array(s) bit-identically
        * to {@link Core#SUPERTREND} over the whole history in the same single pass
        * (no separate batch call needed for the warm-up plot). Output arrays must
        * not alias the inputs or each other, and must hold
        * {@code historyLen - lookback} values — both checked before anything is
        * written, so an undersized array is an {@link IllegalArgumentException}
        * naming it rather than a fault from inside the fill.
        * <p>The range written is on the returned handle:
        * {@link SupertrendStream#outRange()}.
        */
       public SupertrendStream supertrendOpenAndFill( double inHigh[], double inLow[], double inClose[], int optInTimePeriod, double optInMultiplier, double outReal[], int outInteger[] )
       {
          requireArgument("SUPERTREND openAndFill", "inHigh", inHigh);
          requireHistory("SUPERTREND openAndFill", inHigh.length);
          requireArgument("SUPERTREND openAndFill", "inLow", inLow);
          requireArgument("SUPERTREND openAndFill", "inClose", inClose);
          int guardOutLen = openFillCount("SUPERTREND openAndFill", inHigh.length, SUPERTREND_Lookback(optInTimePeriod, optInMultiplier));
          requireHistoryLength("SUPERTREND openAndFill", "inLow", inLow.length, inHigh.length);
          requireHistoryLength("SUPERTREND openAndFill", "inClose", inClose.length, inHigh.length);
          requireLength("SUPERTREND openAndFill", "outReal", outReal, guardOutLen);
          requireLength("SUPERTREND openAndFill", "outInteger", outInteger, guardOutLen);
          if( (Object)outReal == (Object)inHigh || (Object)outReal == (Object)inLow || (Object)outReal == (Object)inClose || (Object)outInteger == (Object)inHigh || (Object)outInteger == (Object)inLow || (Object)outInteger == (Object)inClose || (Object)outReal == (Object)outInteger ) {
             throw new TaLibArgumentException("SUPERTREND openAndFill: " + RetCode.BadParam, RetCode.BadParam);
          }
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          return supertrendOpenAndFillInternal(inHigh, inLow, inClose, 0, optInTimePeriod, optInMultiplier, outBegIdx, outNBElement, outReal, outInteger);
       }
    /* List of contributors:
     *
     *  Initial  Name/description
     *  -------------------------------------------------------------------
     *  MHL      Matthew Lindblom
     *  MF       Mario Fortier
     *
     * Change history:
     *
     *  MMDDYY BY     Description
     *  -------------------------------------------------------------------
     *  120802 MF     Template creation.
     *  032003 MHL    Implementation of T3
     *  040503 MF     Adapt for compatibility with published code
     *                for TradeStation and Metastock.
     *                See "Smoothing Techniques For More Accurate Signals"
     *                from Tim Tillson in Stock&Commodities V16:1 Page 33-37
     *  052603 MF     Adapt code to compile with .NET Managed C++
     *  070226 MF,CC  Allow period of 1: output is an exact copy of the
     *                input, consistent with TA_MA (issues #48, #59). The
     *                natural math is only near-identity at period=1: the
     *                coefficients sum to 1 in real arithmetic but not in
     *                floating point (~1e-14 drift), so the copy is explicit.
     */

       /**
        * Number of leading input bars {@link Core#T3} consumes before it can
        * produce its first value.
        * <p>Equivalently, the index of the first bar with a value when the whole
        * series is requested. Feed at least {@code lookback + 1} bars to get any
        * output.
        * <p>This function is recursive, so the result also includes this
        * {@code Core}'s unstable-period setting — which is why it is an instance
        * method.
        *
        * @param optInTimePeriod EMA period for each of the six stages (default 5;
        *        range 1..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInVFactor Volume factor weighting the coefficients (0 = plain
        *        triple EMA, higher = more DEMA-like sharpening) (default 0.7; range 0..1;
        *        {@code -4e37} selects the default).
        * @return The lookback, or {@code -1} if a parameter is out of range.
        */
       public int T3_Lookback( int optInTimePeriod, double optInVFactor )
       {
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 5;
          } else if( optInTimePeriod < 1 || optInTimePeriod > 100000 ) {
             return -1;
          }
          if( optInVFactor == REAL_DEFAULT ) {
             optInVFactor = 7e-1;
          } else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) ) {
             return -1;
          }
          return 6 * (optInTimePeriod - 1) + this.unstablePeriod[FuncUnstId.T3.ordinal()] ;

       }
       RetCode T3_Impl( int startIdx,
                        int endIdx,
                        double inReal[],
                        int optInTimePeriod,
                        double optInVFactor,
                        MInteger outBegIdx,
                        MInteger outNBElement,
                        double outReal[] )
       {
          int outIdx = 0;
          int lookbackTotal = 0;
          int today = 0;
          int i = 0;
          double k = 0;
          double one_minus_k = 0;
          double e1 = 0;
          double e2 = 0;
          double e3 = 0;
          double e4 = 0;
          double e5 = 0;
          double e6 = 0;
          double c1 = 0;
          double c2 = 0;
          double c3 = 0;
          double c4 = 0;
          double tempReal = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 5;
          } else if( optInTimePeriod < 1 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInVFactor == REAL_DEFAULT ) {
             optInVFactor = 7e-1;
          } else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) ) {
             return RetCode.BadParam;
          }
          /* For an explanation of this function, please read:
           *
           * Magazine articles written by Tim Tillson
           *
           * Essentially, a T3 of time serie 't' is:
           *   EMA1(x,Period) = EMA(x,Period)
           *   EMA2(x,Period) = EMA(EMA1(x,Period),Period)
           *   GD(x,Period,vFactor) = (EMA1(x,Period)*(1+vFactor)) - (EMA2(x,Period)*vFactor)
           *   T3 = GD (GD ( GD(t, Period, vFactor), Period, vFactor), Period, vFactor);
           *
           * T3 offers a moving average with less lags then the
           * traditional EMA.
           *
           * Do not confuse a T3 with EMA3. Both are called "Triple EMA"
           * in the litterature.
           */
          lookbackTotal = 6 * (optInTimePeriod - 1) + this.unstablePeriod[FuncUnstId.T3.ordinal()];
          if( startIdx <= lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             outNBElement.value = 0;
             outBegIdx.value = 0;
             return RetCode.Success ;
          }
          /* No smoothing at period of 1: the output is a copy of the input
           * (same convention as TA_MA for every MAType). Explicit because the
           * coefficients below sum to 1 only in real arithmetic; going through
           * the math would leave ~1e-14 floating-point drift on every value.
           */
          if( optInTimePeriod == 1 ) {
             outBegIdx.value = startIdx;
             outIdx = 0;
             today = startIdx;
             while( today <= endIdx ) {
                outReal[outIdx++] = inReal[today++];
             }
             outNBElement.value = outIdx;
             return RetCode.Success ;
          }
          outBegIdx.value = startIdx;
          today = startIdx - lookbackTotal;
          k = 2.0 / (optInTimePeriod + 1.0);
          one_minus_k = 1.0 - k;
          /* Initialize e1 */
          tempReal = inReal[today++];
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             tempReal += inReal[today++];
          }
          e1 = tempReal / optInTimePeriod;
          /* Initialize e2 */
          tempReal = e1;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             tempReal += e1;
          }
          e2 = tempReal / optInTimePeriod;
          /* Initialize e3 */
          tempReal = e2;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             tempReal += e2;
          }
          e3 = tempReal / optInTimePeriod;
          /* Initialize e4 */
          tempReal = e3;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             tempReal += e3;
          }
          e4 = tempReal / optInTimePeriod;
          /* Initialize e5 */
          tempReal = e4;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             tempReal += e4;
          }
          e5 = tempReal / optInTimePeriod;
          /* Initialize e6 */
          tempReal = e5;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             tempReal += e5;
          }
          e6 = tempReal / optInTimePeriod;
          /* Skip the unstable period */
          while( today <= startIdx ) {
             /* Do the calculation but do not write the output */
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
          }
          /* Calculate the constants */
          tempReal = optInVFactor * optInVFactor;
          c1 = 0 - tempReal * optInVFactor;
          c2 = 3.0 * (tempReal - c1);
          c3 = (0 - 6.0) * tempReal - 3.0 * (optInVFactor - c1);
          c4 = Math.fma(3.0, tempReal, Math.fma(3.0, optInVFactor, 1.0) - c1);
          /* Write the first output */
          outIdx = 0;
          outReal[outIdx++] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          /* Calculate and output the remaining of the range. */
          while( today <= endIdx ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
             outReal[outIdx++] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          }
          /* Indicates to the caller the number of output
           * successfully calculated.
           */
          outNBElement.value = outIdx;
          return RetCode.Success ;
       }
       RetCode T3_Impl( int startIdx,
                        int endIdx,
                        float inReal[],
                        int optInTimePeriod,
                        double optInVFactor,
                        MInteger outBegIdx,
                        MInteger outNBElement,
                        double outReal[] )
       {
          int outIdx = 0;
          int lookbackTotal = 0;
          int today = 0;
          int i = 0;
          double k = 0;
          double one_minus_k = 0;
          double e1 = 0;
          double e2 = 0;
          double e3 = 0;
          double e4 = 0;
          double e5 = 0;
          double e6 = 0;
          double c1 = 0;
          double c2 = 0;
          double c3 = 0;
          double c4 = 0;
          double tempReal = 0;
          if( (startIdx < 0) || (startIdx > MAX_INDEX) ) {
             return RetCode.OutOfRangeStartIndex ;
          }
          if( (endIdx < 0) || (endIdx > MAX_INDEX) || (endIdx < startIdx)) {
             return RetCode.OutOfRangeEndIndex ;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 5;
          } else if( optInTimePeriod < 1 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInVFactor == REAL_DEFAULT ) {
             optInVFactor = 7e-1;
          } else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) ) {
             return RetCode.BadParam;
          }
          lookbackTotal = 6 * (optInTimePeriod - 1) + this.unstablePeriod[FuncUnstId.T3.ordinal()];
          if( startIdx <= lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          if( startIdx > endIdx ) {
             outNBElement.value = 0;
             outBegIdx.value = 0;
             return RetCode.Success ;
          }
          if( optInTimePeriod == 1 ) {
             outBegIdx.value = startIdx;
             outIdx = 0;
             today = startIdx;
             while( today <= endIdx ) {
                outReal[outIdx++] = (double)inReal[today++];
             }
             outNBElement.value = outIdx;
             return RetCode.Success ;
          }
          outBegIdx.value = startIdx;
          today = startIdx - lookbackTotal;
          k = 2.0 / (optInTimePeriod + 1.0);
          one_minus_k = 1.0 - k;
          tempReal = (double)inReal[today++];
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             tempReal += (double)inReal[today++];
          }
          e1 = tempReal / optInTimePeriod;
          tempReal = e1;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             tempReal += e1;
          }
          e2 = tempReal / optInTimePeriod;
          tempReal = e2;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             tempReal += e2;
          }
          e3 = tempReal / optInTimePeriod;
          tempReal = e3;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             tempReal += e3;
          }
          e4 = tempReal / optInTimePeriod;
          tempReal = e4;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             tempReal += e4;
          }
          e5 = tempReal / optInTimePeriod;
          tempReal = e5;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             tempReal += e5;
          }
          e6 = tempReal / optInTimePeriod;
          while( today <= startIdx ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
          }
          tempReal = optInVFactor * optInVFactor;
          c1 = 0 - tempReal * optInVFactor;
          c2 = 3.0 * (tempReal - c1);
          c3 = (0 - 6.0) * tempReal - 3.0 * (optInVFactor - c1);
          c4 = Math.fma(3.0, tempReal, Math.fma(3.0, optInVFactor, 1.0) - c1);
          outIdx = 0;
          outReal[outIdx++] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          while( today <= endIdx ) {
             e1 = Math.fma(one_minus_k, e1, k * (double)inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
             outReal[outIdx++] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          }
          outNBElement.value = outIdx;
          return RetCode.Success ;
       }
       /**
        * Tillson's T3: a low-lag moving average built from six chained EMAs,
        * combined via volume-factor-weighted coefficients. Not the same as EMA3,
        * despite both being called "triple EMA".
        * <p><b>Formula</b>
        * <pre>{@code
        * k = 2/(period+1); e1=EMA(x), e2=EMA(e1), ... e6=EMA(e5) (six chained EMAs).
        * v = vFactor: c1 = -v^3; c2 = 3(v^2 - c1); c3 = -6v^2 - 3(v - c1); c4 = 1 + 3v - c1 + 3v^2.
        * T3 = c1*e6 + c2*e5 + c3*e4 + c4*e3
        * }</pre>
        * <p><b>Notes</b>
        * <ul>
        * <li>A period of 1 performs no smoothing: the output is a copy of the input. Allowed since 0.6.5 (issues #48/#59).</li>
        * </ul>
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#T3_Lookback} is a <b>success with no
        * values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inReal Source series to smooth.
        * @param optInTimePeriod EMA period for each of the six stages (default 5;
        *        range 1..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInVFactor Volume factor weighting the coefficients (0 = plain
        *        triple EMA, higher = more DEMA-like sharpening) (default 0.7; range 0..1;
        *        {@code -4e37} selects the default).
        * @param outReal T3 smoothed line. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#EMA
        * @see Core#DEMA
        * @see Core#TEMA
        * @see Core#MA
        */
       public OutRange T3( int startIdx,
                           int endIdx,
                           double inReal[],
                           int optInTimePeriod,
                           double optInVFactor,
                           double outReal[] )
       {
          requireIndexRange("T3", startIdx, endIdx);
          int guardStart = clampedStart("T3", startIdx, T3_Lookback(optInTimePeriod, optInVFactor));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("T3", "inReal", inReal, guardInLen);
          requireLength("T3", "outReal", outReal, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = T3_Impl(startIdx, endIdx, inReal, optInTimePeriod, optInVFactor, outBegIdx, outNBElement, outReal);
          if( retCode != RetCode.Success ) {
             throw failure("T3", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
       /**
        * Tillson's T3: a low-lag moving average built from six chained EMAs,
        * combined via volume-factor-weighted coefficients. Not the same as EMA3,
        * despite both being called "triple EMA".
        * <p><b>Formula</b>
        * <pre>{@code
        * k = 2/(period+1); e1=EMA(x), e2=EMA(e1), ... e6=EMA(e5) (six chained EMAs).
        * v = vFactor: c1 = -v^3; c2 = 3(v^2 - c1); c3 = -6v^2 - 3(v - c1); c4 = 1 + 3v - c1 + 3v^2.
        * T3 = c1*e6 + c2*e5 + c3*e4 + c4*e3
        * }</pre>
        * <p><b>Notes</b>
        * <ul>
        * <li>A period of 1 performs no smoothing: the output is a copy of the input. Allowed since 0.6.5 (issues #48/#59).</li>
        * </ul>
        * <p>This is the {@code float[]} overload. The arithmetic is performed in
        * {@code double} before being written to the {@code double[]} output, so a
        * result beyond {@code float} range is still representable.
        * <p>Values are written only where the indicator is defined. The returned
        * {@link OutRange} says where they start and how many there are; nothing
        * outside that range is touched, and the library never pads with NaN. A
        * valid range shorter than {@link Core#T3_Lookback} is a <b>success with no
        * values</b> ({@code count() == 0}), not an error.
        *
        * @param startIdx First bar of the requested range (inclusive).
        * @param endIdx Last bar of the requested range (inclusive).
        * @param inReal Source series to smooth.
        * @param optInTimePeriod EMA period for each of the six stages (default 5;
        *        range 1..100000; {@code Integer.MIN_VALUE} selects the default).
        * @param optInVFactor Volume factor weighting the coefficients (0 = plain
        *        triple EMA, higher = more DEMA-like sharpening) (default 0.7; range 0..1;
        *        {@code -4e37} selects the default).
        * @param outReal T3 smoothed line. Must hold at least
        *        {@code endIdx - startIdx + 1} values.
        * @return The range written: {@code begIdx} is the first bar with a value,
        *        {@code count} how many were written.
        * @throws IndexOutOfBoundsException if {@code startIdx} or {@code endIdx} is
        *        negative or above {@link Core#MAX_INDEX}, or {@code endIdx < startIdx}.
        * @throws IllegalArgumentException if an optional parameter is outside its
        *        documented range, two outputs share one array, or an array is absent or
        *        too short for the range requested — any input this function
        *        <i>declares</i> that does not reach {@code endIdx}, or an output that
        *        cannot hold the values produced. Declared, not read: a few candlestick
        *        patterns take an OHLC series they never index, and it is required all the
        *        same. An output this function documents as declinable is the one
        *        exception: {@code null} is how you decline it. Checked before anything is
        *        written, so a rejected call leaves every buffer untouched.
        *
        * @see Core#EMA
        * @see Core#DEMA
        * @see Core#TEMA
        * @see Core#MA
        */
       public OutRange T3( int startIdx,
                           int endIdx,
                           float inReal[],
                           int optInTimePeriod,
                           double optInVFactor,
                           double outReal[] )
       {
          requireIndexRange("T3", startIdx, endIdx);
          int guardStart = clampedStart("T3", startIdx, T3_Lookback(optInTimePeriod, optInVFactor));
          int guardInLen = endIdx + 1;
          int guardOutLen = guardStart > endIdx ? 0 : endIdx - guardStart + 1;
          requireLength("T3", "inReal", inReal, guardInLen);
          requireLength("T3", "outReal", outReal, guardOutLen);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          RetCode retCode = T3_Impl(startIdx, endIdx, inReal, optInTimePeriod, optInVFactor, outBegIdx, outNBElement, outReal);
          if( retCode != RetCode.Success ) {
             throw failure("T3", retCode);
          }
          return new OutRange(outBegIdx.value, outNBElement.value);
       }
    /**** Streaming API *****/

       /**
        * A live T3 stream (unrelated to {@code java.util.stream}): one value per
        * closed bar, bit-identical to {@link Core#T3} over the same series.
        * Open with {@link Core#t3Open}; there is no close — the handle is
        * ordinary heap state, unreferenced handles are simply garbage-collected.
        * <p>Concurrency: a handle is single-writer — {@code update}, {@code peek},
        * {@code value} and {@code clone} must not race with an {@code update} on
        * the same handle. With no concurrent {@code update}, {@code peek}/
        * {@code value}/{@code clone} never write the stream and may be called
        * concurrently after safe publication. Independent streams (a
        * {@code clone()} result included) are fully independent.
        * <p>Not serializable by design: to checkpoint, retain the history and
        * re-open — the result is bit-identical by contract.
        */
       public static final class T3Stream {
          Core core;
          int optInTimePeriod;
          double optInVFactor;
          double k;
          double one_minus_k;
          double e1;
          double e2;
          double e3;
          double e4;
          double e5;
          double e6;
          double c1;
          double c2;
          double c3;
          double c4;
          double cur_outReal;
          int outRangeBegIdx;
          int outRangeCount;

          T3Stream( Core core ) { this.core = core; }

          /**
           * The bars this stream has an output for, in the input series'
           * coordinates: {@code [begIdx, begIdx + count)}.
           * <p>It is what {@link Core#T3} reports over the same bars: the
           * opener sets it to {@code (lookback, historyLen - lookback)}, every
           * {@code update} adds one to the count — a bar rejected for being
           * non-finite included, because it still happened — {@code peek} leaves
           * it alone, and {@code clone()} carries it verbatim. A plain
           * {@code open} hands back only the last value, a subset of this range,
           * because the caller chose not to take the fill.
           */
          public OutRange outRange() { return new OutRange(outRangeBegIdx, outRangeCount); }

          T3Stream( T3Stream other ) {
             this.core = other.core;
             this.optInTimePeriod = other.optInTimePeriod;
             this.optInVFactor = other.optInVFactor;
             this.k = other.k;
             this.one_minus_k = other.one_minus_k;
             this.e1 = other.e1;
             this.e2 = other.e2;
             this.e3 = other.e3;
             this.e4 = other.e4;
             this.e5 = other.e5;
             this.e6 = other.e6;
             this.c1 = other.c1;
             this.c2 = other.c2;
             this.c3 = other.c3;
             this.c4 = other.c4;
             this.cur_outReal = other.cur_outReal;
             this.outRangeBegIdx = other.outRangeBegIdx;
             this.outRangeCount = other.outRangeCount;
          }

          /**
           * Commit one closed bar, returning the new current value.
           * Never allocates handle state.
           * <p>Throws {@link IllegalArgumentException} if any bar value is not
           * finite (NaN or an infinity). That check runs before anything is
           * written, so the state is left exactly as it was: the rejected bar's
           * output is the previous value, held, and {@link #value()} answers it.
           * The stream stays usable, so skip the bar or re-open on a clean
           * history. {@link #outRange()} does advance: the bar happened and
           * occupies a position in the series, so the handle counts it, which is
           * what keeps two handles on one feed aligned when only one rejects.
           * This is the one place the streaming tier is stricter than
           * the batch API, which computes on whatever it is given: a handle
           * retains its state, so a single non-finite bar would poison every
           * later value it produces.
           */
          public double update( double inReal ) {
             if( !Double.isFinite(inReal) ) {
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                throw new TaLibArgumentException("T3 update: BadParam", RetCode.BadParam);
             }
             core.t3StepImpl(this, inReal);
             if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             return this.cur_outReal;
          }

          /**
           * Commit {@code n} closed bars and write their {@code n} values, in one
           * call — exactly {@code n} back-to-back {@code update} calls, with one
           * set of argument checks instead of {@code n}. {@code n} is
           * {@code inReal.length}; the outputs must hold at least that many, and must
           * not be the same array as an input or as each other.
           * <p>{@link #outRange()} counts what this call took in, which is what makes a
           * rejection readable: a non-finite bar {@code k} throws
           * {@link IllegalArgumentException} exactly as {@code update} would, with
           * the bars before {@code k} committed and written, bar {@code k} and
           * everything after it not, and the count advanced by {@code k + 1} —
           * the committed bars plus the rejected one.
           */
          public void updateAndFill( double inReal[], double outReal[] ) {
             requireArgument("T3 updateAndFill", "inReal", inReal);
             requireArgument("T3 updateAndFill", "outReal", outReal);
             final int barCount = inReal.length;
             if( outReal.length < barCount || (Object)outReal == (Object)inReal )
                throw new TaLibArgumentException("T3 updateAndFill: BadParam", RetCode.BadParam);
             for( int i = 0; i < barCount; i++ ) {
                if( !Double.isFinite(inReal[i]) ) {
                   if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
                   throw new TaLibArgumentException("T3 updateAndFill: BadParam", RetCode.BadParam);
                }
                core.t3StepImpl(this, inReal[i]);
                outReal[i] = this.cur_outReal;
                if( this.outRangeCount < MAX_INDEX ) this.outRangeCount++;
             }
          }

          /**
           * Evaluate a forming bar without committing — bit-identical to what the
           * next {@code update} with the same bar would return — the same
           * transition, with every store it would make carried in a local instead.
           * Never writes this handle, so peeks may
           * run concurrently with each other. It copies nothing: the frame runs against this handle, reading its
           * buffers and storing what the step would commit into locals, so the cost
           * does not grow with the period and {@code peek} never allocates.
           */
          public double peek( double inReal ) {
             if( !Double.isFinite(inReal) )
                throw new TaLibArgumentException("T3 peek: BadParam", RetCode.BadParam);
             T3Stream sp = this;
             double cur_outReal = sp.cur_outReal;
             double e1 = sp.e1;
             double e2 = sp.e2;
             double e3 = sp.e3;
             double e4 = sp.e4;
             double e5 = sp.e5;
             double e6 = sp.e6;
             if( sp.optInTimePeriod == 1 ) {
                cur_outReal = inReal;
                return cur_outReal ;
             }
             e1 = Math.fma(sp.one_minus_k, e1, sp.k * inReal);
             e2 = Math.fma(sp.one_minus_k, e2, sp.k * e1);
             e3 = Math.fma(sp.one_minus_k, e3, sp.k * e2);
             e4 = Math.fma(sp.one_minus_k, e4, sp.k * e3);
             e5 = Math.fma(sp.one_minus_k, e5, sp.k * e4);
             e6 = Math.fma(sp.one_minus_k, e6, sp.k * e5);
             cur_outReal = Math.fma(sp.c4, e3, Math.fma(sp.c3, e4, Math.fma(sp.c1, e6, sp.c2 * e5)));
             return cur_outReal;
          }

          /**
           * The value at the last bar this stream counted — the bar
           * {@link #outRange()} ends on. The last history bar right after open,
           * then whatever the latest accepted {@code update} returned.
           * A pure field read; {@code peek} does not change it.
           */
          public double value() {
             return this.cur_outReal;
          }

          /**
           * An independent fork of this stream: both evolve separately from here
           * on. Buffers are copied and sub-streams cloned recursively; the
           * {@link Core} reference is shared, since a {@code Core} is immutable
           * for a stream's lifetime.
           *
           * <p>Not the {@code Cloneable} protocol: this calls a copy constructor,
           * never {@code super.clone()}, so it throws nothing.
           *
           * @return an independent stream at the same bar
           */
          @Override
          public T3Stream clone() {
             return new T3Stream(this);
          }
       }
       void t3StepImpl( T3Stream sp, double inReal )
       {
          if( sp.optInTimePeriod == 1 ) {
             sp.cur_outReal = inReal;
             return ;
          }
          sp.e1 = Math.fma(sp.one_minus_k, sp.e1, sp.k * inReal);
          sp.e2 = Math.fma(sp.one_minus_k, sp.e2, sp.k * sp.e1);
          sp.e3 = Math.fma(sp.one_minus_k, sp.e3, sp.k * sp.e2);
          sp.e4 = Math.fma(sp.one_minus_k, sp.e4, sp.k * sp.e3);
          sp.e5 = Math.fma(sp.one_minus_k, sp.e5, sp.k * sp.e4);
          sp.e6 = Math.fma(sp.one_minus_k, sp.e6, sp.k * sp.e5);
          sp.cur_outReal = Math.fma(sp.c4, sp.e3, Math.fma(sp.c3, sp.e4, Math.fma(sp.c1, sp.e6, sp.c2 * sp.e5)));
       }
       private RetCode t3OpenImpl( T3Stream sp, double inReal[], int startIdx, int optInTimePeriod, double optInVFactor, MInteger outBegIdx, MInteger outNBElement, double outReal[], int outStride )
       {
          int outIdx = 0;
          int lookbackTotal = 0;
          int today = 0;
          int i = 0;
          double k = 0;
          double one_minus_k = 0;
          double e1 = 0;
          double e2 = 0;
          double e3 = 0;
          double e4 = 0;
          double e5 = 0;
          double e6 = 0;
          double c1 = 0;
          double c2 = 0;
          double c3 = 0;
          double c4 = 0;
          double tempReal = 0;
          int historyLen = inReal.length;
          int endIdx = historyLen - 1;
          if( historyLen < 1 ) {
             return RetCode.OutOfRangeStartIndex;
          }
          if( historyLen > MAX_INDEX + 1 ) {
             return RetCode.OutOfRangeEndIndex;
          }
          if( optInTimePeriod == Integer.MIN_VALUE ) {
             optInTimePeriod = 5;
          } else if( optInTimePeriod < 1 || optInTimePeriod > 100000 ) {
             return RetCode.BadParam;
          }
          if( optInVFactor == REAL_DEFAULT ) {
             optInVFactor = 7e-1;
          } else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) ) {
             return RetCode.BadParam;
          }
          if( startIdx > endIdx ) {
             outBegIdx.value = 0;
             outNBElement.value = 0;
             return RetCode.InsufficientHistory;
          }
          if( optInTimePeriod == 1 ) {
             int fillLb = T3_Lookback(optInTimePeriod, optInVFactor);
             if( startIdx > fillLb ) fillLb = startIdx;
             if( historyLen < fillLb + 1 ) {
                return RetCode.InsufficientHistory;
             }
             sp.optInTimePeriod = optInTimePeriod;
             sp.optInVFactor = optInVFactor;
             sp.k = 0.0;
             sp.one_minus_k = 0.0;
             sp.e1 = 0.0;
             sp.e2 = 0.0;
             sp.e3 = 0.0;
             sp.e4 = 0.0;
             sp.e5 = 0.0;
             sp.e6 = 0.0;
             sp.c1 = 0.0;
             sp.c2 = 0.0;
             sp.c3 = 0.0;
             sp.c4 = 0.0;
             outBegIdx.value = fillLb;
             outNBElement.value = historyLen - fillLb;
             if( outStride == 0 ) {
                outReal[0] = inReal[historyLen - 1];
             } else {
                for( int fillIdx = 0; fillIdx < historyLen - fillLb; fillIdx++ ) {
                   outReal[fillIdx] = inReal[fillLb + fillIdx];
                }
             }
             sp.cur_outReal = outReal[(outNBElement.value - 1) * outStride];
             return RetCode.Success;
          }
          /* For an explanation of this function, please read:
           *
           * Magazine articles written by Tim Tillson
           *
           * Essentially, a T3 of time serie 't' is:
           *   EMA1(x,Period) = EMA(x,Period)
           *   EMA2(x,Period) = EMA(EMA1(x,Period),Period)
           *   GD(x,Period,vFactor) = (EMA1(x,Period)*(1+vFactor)) - (EMA2(x,Period)*vFactor)
           *   T3 = GD (GD ( GD(t, Period, vFactor), Period, vFactor), Period, vFactor);
           *
           * T3 offers a moving average with less lags then the
           * traditional EMA.
           *
           * Do not confuse a T3 with EMA3. Both are called "Triple EMA"
           * in the litterature.
           */
          lookbackTotal = 6 * (optInTimePeriod - 1) + this.unstablePeriod[FuncUnstId.T3.ordinal()];
          if( startIdx <= lookbackTotal ) {
             startIdx = lookbackTotal;
          }
          /* Make sure there is still something to evaluate. */
          if( startIdx > endIdx ) {
             outNBElement.value = 0;
             outBegIdx.value = 0;
             return RetCode.InsufficientHistory ;
          }
          outBegIdx.value = startIdx;
          today = startIdx - lookbackTotal;
          k = 2.0 / (optInTimePeriod + 1.0);
          one_minus_k = 1.0 - k;
          /* Initialize e1 */
          tempReal = inReal[today++];
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             tempReal += inReal[today++];
          }
          e1 = tempReal / optInTimePeriod;
          /* Initialize e2 */
          tempReal = e1;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             tempReal += e1;
          }
          e2 = tempReal / optInTimePeriod;
          /* Initialize e3 */
          tempReal = e2;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             tempReal += e2;
          }
          e3 = tempReal / optInTimePeriod;
          /* Initialize e4 */
          tempReal = e3;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             tempReal += e3;
          }
          e4 = tempReal / optInTimePeriod;
          /* Initialize e5 */
          tempReal = e4;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             tempReal += e4;
          }
          e5 = tempReal / optInTimePeriod;
          /* Initialize e6 */
          tempReal = e5;
          for( i = optInTimePeriod - 1; i > 0; i -= 1 ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             tempReal += e5;
          }
          e6 = tempReal / optInTimePeriod;
          /* Skip the unstable period */
          while( today <= startIdx ) {
             /* Do the calculation but do not write the output */
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
          }
          /* Calculate the constants */
          tempReal = optInVFactor * optInVFactor;
          c1 = 0 - tempReal * optInVFactor;
          c2 = 3.0 * (tempReal - c1);
          c3 = (0 - 6.0) * tempReal - 3.0 * (optInVFactor - c1);
          c4 = Math.fma(3.0, tempReal, Math.fma(3.0, optInVFactor, 1.0) - c1);
          /* Write the first output */
          outIdx = 0;
          outReal[outIdx++ * outStride] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          /* Calculate and output the remaining of the range. */
          while( today <= endIdx ) {
             e1 = Math.fma(one_minus_k, e1, k * inReal[today++]);
             e2 = Math.fma(one_minus_k, e2, k * e1);
             e3 = Math.fma(one_minus_k, e3, k * e2);
             e4 = Math.fma(one_minus_k, e4, k * e3);
             e5 = Math.fma(one_minus_k, e5, k * e4);
             e6 = Math.fma(one_minus_k, e6, k * e5);
             outReal[outIdx++ * outStride] = Math.fma(c4, e3, Math.fma(c3, e4, Math.fma(c1, e6, c2 * e5)));
          }
          /* Indicates to the caller the number of output
           * successfully calculated.
           */
          outNBElement.value = outIdx;
          /* Capture the live batch state into the handle. */
          sp.optInTimePeriod = optInTimePeriod;
          sp.optInVFactor = optInVFactor;
          sp.k = k;
          sp.one_minus_k = one_minus_k;
          sp.e1 = e1;
          sp.e2 = e2;
          sp.e3 = e3;
          sp.e4 = e4;
          sp.e5 = e5;
          sp.e6 = e6;
          sp.c1 = c1;
          sp.c2 = c2;
          sp.c3 = c3;
          sp.c4 = c4;
          sp.cur_outReal = outReal[(outNBElement.value - 1) * outStride];
          return RetCode.Success;
       }
       /* t3OpenAndFill anchored at startIdx — the composed-open fusion seam. */
       T3Stream t3OpenAndFillInternal( double inReal[], int startIdx, int optInTimePeriod, double optInVFactor, MInteger outBegIdx, MInteger outNBElement, double outReal[] )
       {
          T3Stream sp = new T3Stream(this);
          RetCode retCode = t3OpenImpl(sp, inReal, startIdx, optInTimePeriod, optInVFactor, outBegIdx, outNBElement, outReal, 1);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("T3 openAndFill: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("T3 openAndFill: internal error", retCode);
          }
          throw new TaLibArgumentException("T3 openAndFill: " + retCode, retCode);
       }
       /* Internal startIdx-anchored open behind t3Open (composition seam). */
       T3Stream t3OpenInternal( double inReal[], int startIdx, int optInTimePeriod, double optInVFactor )
       {
          T3Stream sp = new T3Stream(this);
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          double[] sink_outReal = new double[1];
          RetCode retCode = t3OpenImpl(sp, inReal, startIdx, optInTimePeriod, optInVFactor, outBegIdx, outNBElement, sink_outReal, 0);
          sp.outRangeBegIdx = outBegIdx.value;
          sp.outRangeCount = outNBElement.value;
          if( retCode == RetCode.Success ) {
             return sp;
          }
          if( retCode == RetCode.InsufficientHistory ) {
             throw new InsufficientHistoryException("T3 open: history shorter than lookback + 1");
          }
          if( retCode == RetCode.InternalError ) {
             throw new TaLibStateException("T3 open: internal error", retCode);
          }
          throw new TaLibArgumentException("T3 open: " + retCode, retCode);
       }
       /**
        * Open a live T3 stream over the warm-up history; the handle's
        * {@code value()} starts at the last history bar's value — bit-identical
        * to {@link Core#T3} at that bar.
        * <p>The history must hold at least {@code T3_Lookback(...) + 1} bars
        * (unstable-period aware), or {@link InsufficientHistoryException} is
        * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
        * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
        * default, as in the batch API). An EMPTY history throws
        * {@link IndexOutOfBoundsException} — its implied {@code startIdx} of 0
        * names no bar — and a null argument {@link IllegalArgumentException},
        * both ahead of everything above.
        */
       public T3Stream t3Open( double inReal[], int optInTimePeriod, double optInVFactor )
       {
          requireArgument("T3 open", "inReal", inReal);
          requireHistory("T3 open", inReal.length);
          return t3OpenInternal(inReal, 0, optInTimePeriod, optInVFactor);
       }
       /**
        * {@link Core#t3Open} that also fills the output array(s) bit-identically
        * to {@link Core#T3} over the whole history in the same single pass
        * (no separate batch call needed for the warm-up plot). Output arrays must
        * not alias the inputs or each other, and must hold
        * {@code historyLen - lookback} values — both checked before anything is
        * written, so an undersized array is an {@link IllegalArgumentException}
        * naming it rather than a fault from inside the fill.
        * <p>The range written is on the returned handle:
        * {@link T3Stream#outRange()}.
        */
       public T3Stream t3OpenAndFill( double inReal[], int optInTimePeriod, double optInVFactor, double outReal[] )
       {
          requireArgument("T3 openAndFill", "inReal", inReal);
          requireHistory("T3 openAndFill", inReal.length);
          int guardOutLen = openFillCount("T3 openAndFill", inReal.length, T3_Lookback(optInTimePeriod, optInVFactor));
          requireLength("T3 openAndFill", "outReal", outReal, guardOutLen);
          if( (Object)outReal == (Object)inReal ) {
             throw new TaLibArgumentException("T3 openAndFill: " + RetCode.BadParam, RetCode.BadParam);
          }
          MInteger outBegIdx = new MInteger();
          MInteger outNBElement = new MInteger();
          return t3OpenAndFillInternal(inReal, 0, optInTimePeriod, optInVFactor, outBegIdx, outNBElement, outReal);
       }
